@font-face{font-family:'Tactical';src:local('Bahnschrift'),local('DIN Alternate'),local('Arial Narrow');font-stretch:condensed;}
:root{
  --bg:#05070a; --ink:#e9e5dc; --dim:#8b929a; --faint:#4d555e;
  --amber:#f2ae55; --amber-hot:#ffc978; --red:#ff4438; --teal:#7fe6cd;
  --line:rgba(233,229,220,.16); --panel:rgba(9,12,16,.88);
  --font:'Tactical','Bahnschrift Condensed','DIN Condensed','Arial Narrow',Arial,sans-serif;
  --mono:'SF Mono','Roboto Mono','Consolas',monospace;
}
*{box-sizing:border-box;-webkit-tap-highlight-color:transparent;}
html,body{margin:0;padding:0;height:100%;background:var(--bg);color:var(--ink);font-family:var(--font);overflow:hidden;}
body{overscroll-behavior:none;user-select:none;-webkit-user-select:none;}
#app{position:fixed;inset:0;overflow:hidden;background:#05070a;}
#game-canvas{position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:none;cursor:crosshair;}
.hidden{display:none!important;}
.screen{position:absolute;inset:0;z-index:30;display:flex;}
button{font-family:inherit;color:inherit;}
::selection{background:var(--amber);color:#05070a;}

/* ---------- loading ---------- */
.loading-screen{background:radial-gradient(ellipse at 50% 40%,#10161f 0%,#05070a 68%);flex-direction:column;align-items:center;justify-content:center;gap:10px;z-index:100;transition:opacity .7s ease;}
.loading-screen.out{opacity:0;pointer-events:none;}
.load-mark{width:74px;height:74px;color:var(--amber);margin-bottom:18px;filter:drop-shadow(0 0 18px rgba(242,174,85,.25));animation:pulse 2.4s ease-in-out infinite;}
.load-title{font-size:44px;letter-spacing:.46em;font-weight:700;margin-left:.46em;}
.load-sub{font-size:11px;letter-spacing:.34em;color:var(--dim);margin-top:2px;}
.load-track{width:min(340px,70vw);height:1px;background:rgba(255,255,255,.13);margin-top:34px;position:relative;overflow:hidden;}
#load-fill{position:absolute;inset:0;width:0%;background:var(--amber);transition:width .3s ease;box-shadow:0 0 10px var(--amber);}
.load-status{font-family:var(--mono);font-size:9px;letter-spacing:.22em;color:var(--faint);margin-top:10px;}
@keyframes pulse{0%,100%{opacity:.6}50%{opacity:1}}

/* ---------- menu ---------- */
.menu-screen{flex-direction:column;justify-content:space-between;padding:0;background:
  linear-gradient(90deg,rgba(4,6,9,.93) 0%,rgba(4,6,9,.72) 38%,rgba(4,6,9,.08) 68%,rgba(4,6,9,.55) 100%),
  linear-gradient(0deg,rgba(4,6,9,.92) 0%,transparent 34%,transparent 74%,rgba(4,6,9,.8) 100%);
  overflow:hidden;}
.menu-grid{position:absolute;inset:0;background-image:linear-gradient(rgba(255,255,255,.035) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.035) 1px,transparent 1px);background-size:64px 64px;mask-image:radial-gradient(ellipse at 30% 50%,black 0%,transparent 70%);opacity:.5;pointer-events:none;}
.menu-top{display:flex;justify-content:space-between;align-items:center;padding:24px 38px;font-size:10px;letter-spacing:.2em;color:var(--dim);z-index:2;border-bottom:1px solid rgba(255,255,255,.06);}
.brand{display:flex;align-items:center;gap:10px;color:var(--ink);}
.brand-mark{color:var(--amber);font-size:9px;}
.brand-sep{color:var(--faint);}
.dim{color:var(--faint);}
.menu-top-right{display:flex;align-items:center;gap:8px;font-family:var(--mono);font-size:9px;color:var(--faint);}
.live-dot{width:5px;height:5px;background:var(--teal);border-radius:50%;box-shadow:0 0 8px var(--teal);animation:pulse 2s infinite;}
.menu-main{position:relative;z-index:2;padding:0 7vw;max-width:820px;margin-top:auto;margin-bottom:auto;transform:translateY(-1%);}
.eyebrow{display:flex;align-items:center;gap:14px;font-family:var(--mono);font-size:9px;letter-spacing:.3em;color:var(--amber);margin-bottom:14px;}
.rule{width:34px;height:1px;background:var(--amber);opacity:.7;}
.title{margin:0;font-size:clamp(74px,11.4vw,168px);line-height:.78;letter-spacing:.015em;font-weight:800;color:#f2eee5;text-shadow:0 4px 50px rgba(0,0,0,.65);}
.title span{-webkit-text-stroke:1.5px rgba(242,174,85,.75);color:transparent;text-shadow:0 0 50px rgba(242,174,85,.15);}
.title-rule{display:flex;align-items:center;gap:16px;margin:22px 0 20px;max-width:630px;}
.title-rule span{flex:1;height:1px;background:linear-gradient(90deg,var(--amber),transparent);opacity:.55;}
.title-rule span:last-child{background:linear-gradient(90deg,transparent,var(--amber));}
.title-rule i{font-style:normal;font-size:12px;letter-spacing:.52em;color:var(--amber);padding-left:.52em;}
.menu-blurb{max-width:490px;font-size:14px;line-height:1.65;color:#aab0b6;margin:0 0 30px;font-family:var(--mono);font-weight:400;letter-spacing:.01em;}
.menu-actions{display:flex;flex-direction:column;gap:5px;max-width:370px;}
.btn{position:relative;display:flex;align-items:center;gap:16px;padding:13px 16px;background:rgba(255,255,255,.025);border:1px solid rgba(255,255,255,.13);cursor:pointer;text-align:left;transition:all .18s ease;letter-spacing:.19em;font-size:13px;font-weight:600;overflow:hidden;}
.btn:before{content:"";position:absolute;left:0;top:0;bottom:0;width:2px;background:transparent;transition:background .18s;}
.btn:hover{background:rgba(242,174,85,.09);border-color:rgba(242,174,85,.55);padding-left:22px;}
.btn:hover:before{background:var(--amber);}
.btn-index{font-family:var(--mono);font-size:9px;color:var(--faint);letter-spacing:.05em;width:16px;}
.btn-label{flex:1;}
.btn-arrow{color:var(--amber);opacity:0;transform:translateX(-6px);transition:all .18s;}
.btn:hover .btn-arrow{opacity:1;transform:translateX(0);}
.btn-primary{background:linear-gradient(90deg,rgba(242,174,85,.97),rgba(238,158,61,.93));color:#100d08;border-color:var(--amber);box-shadow:0 6px 34px rgba(242,174,85,.14);}
.btn-primary .btn-index{color:rgba(16,13,8,.5);}
.btn-primary .btn-arrow{color:#100d08;opacity:1;transform:none;}
.btn-primary:hover{background:linear-gradient(90deg,#ffc978,#f2ae55);padding-left:22px;}
.btn-primary:before{background:#100d08;}
.menu-meta{display:flex;gap:52px;margin-top:34px;padding-top:18px;border-top:1px solid rgba(255,255,255,.09);max-width:620px;}
.menu-meta div{display:flex;flex-direction:column;gap:6px;}
.menu-meta label{font-family:var(--mono);font-size:8px;letter-spacing:.24em;color:var(--faint);}
.menu-meta span{font-family:var(--mono);font-size:11px;letter-spacing:.1em;color:#cfd2d4;}
.menu-side{position:absolute;right:46px;top:50%;transform:translateY(-50%);z-index:2;display:flex;flex-direction:column;align-items:flex-end;gap:20px;font-family:var(--mono);font-size:9px;letter-spacing:.13em;color:#898f95;text-align:right;}
.side-line{width:120px;height:1px;background:rgba(255,255,255,.2);}
.side-line.short{width:46px;background:var(--amber);opacity:.7;}
.side-text{font-size:13px;line-height:1.9;letter-spacing:.18em;color:#c3c6c7;}
.side-coord{line-height:2;color:#727980;}
.side-barcode{width:88px;height:30px;background:repeating-linear-gradient(90deg,#9aa0a5 0 1px,transparent 1px 3px,#9aa0a5 3px 5px,transparent 5px 8px);opacity:.35;}
.side-foot{line-height:1.9;color:#5d646b;font-size:8px;}
.menu-footer{display:flex;justify-content:space-between;padding:18px 38px;border-top:1px solid rgba(255,255,255,.06);font-family:var(--mono);font-size:8px;letter-spacing:.18em;color:#555d65;z-index:2;}
.warn{color:#7c6a55;}
.menu-hint{color:#5d646b;}

/* ---------- modal panels ---------- */
.modal-screen{z-index:50;align-items:center;justify-content:center;background:rgba(2,4,6,.72);backdrop-filter:blur(9px);padding:24px;}
.panel{width:min(540px,94vw);background:linear-gradient(160deg,rgba(15,19,24,.98),rgba(6,8,11,.99));border:1px solid rgba(255,255,255,.15);padding:32px;position:relative;box-shadow:0 30px 120px rgba(0,0,0,.75);}
.panel:before,.panel:after{content:"";position:absolute;width:16px;height:16px;border-color:var(--amber);border-style:solid;opacity:.8;}
.panel:before{top:-1px;left:-1px;border-width:1px 0 0 1px;}
.panel:after{bottom:-1px;right:-1px;border-width:0 1px 1px 0;}
.panel.wide-panel{width:min(900px,94vw);}
.panel-head{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:1px solid var(--line);padding-bottom:20px;margin-bottom:24px;}
.panel-kicker{font-family:var(--mono);font-size:9px;letter-spacing:.28em;color:var(--amber);margin-bottom:8px;}
.panel h2{font-size:34px;letter-spacing:.08em;margin:0;font-weight:700;}
.panel h2 em{font-style:normal;color:var(--amber);}
.panel h3{font-family:var(--mono);font-size:9px;letter-spacing:.24em;color:var(--amber);margin:0 0 10px;}
.x-btn{background:none;border:1px solid rgba(255,255,255,.16);width:32px;height:32px;cursor:pointer;color:var(--dim);font-size:12px;transition:.15s;}
.x-btn:hover{color:var(--ink);border-color:var(--ink);}
.brief-grid{display:grid;grid-template-columns:1fr 1fr;gap:40px;}
.brief-col p{font-family:var(--mono);font-size:11px;line-height:1.75;color:#a3a9ae;margin:0 0 14px;}
.brief-col b{color:var(--ink);}
.brief-col h3:not(:first-child){margin-top:26px;}
.obj-list{list-style:none;padding:0;margin:0 0 22px;counter-reset:obj;}
.obj-list li{display:flex;gap:13px;font-family:var(--mono);font-size:11px;line-height:1.5;color:#c3c7ca;padding:9px 0;border-bottom:1px solid rgba(255,255,255,.06);}
.obj-list span{color:var(--amber);font-size:9px;padding-top:2px;}
.intel-strip{display:flex;gap:0;border:1px solid var(--line);margin:0 0 18px;}
.intel-strip div{flex:1;padding:11px 13px;border-right:1px solid var(--line);display:flex;flex-direction:column;gap:4px;}
.intel-strip div:last-child{border:0;}
.intel-strip label{font-family:var(--mono);font-size:7px;letter-spacing:.2em;color:var(--faint);}
.intel-strip b{font-family:var(--mono);font-size:12px;letter-spacing:.1em;}
.threat{color:var(--red);}
.small-note{font-family:var(--mono);font-size:9px!important;color:#697077!important;line-height:1.7!important;margin-top:8px!important;}
.small-note.center{text-align:center;}
.panel-actions{display:flex;gap:8px;margin-top:26px;justify-content:flex-end;}
.panel-actions.column{flex-direction:column;align-items:stretch;}
.btn.compact{justify-content:center;font-size:11px;padding:12px 18px;letter-spacing:.2em;}
.btn.compact .btn-arrow{opacity:1;transform:none;}
.control-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 36px;}
.control-grid>div{display:flex;align-items:center;gap:6px;padding:11px 0;border-bottom:1px solid rgba(255,255,255,.06);}
.control-grid span{margin-left:auto;font-family:var(--mono);font-size:9px;letter-spacing:.15em;color:#a1a7ac;}
kbd{font-family:var(--mono);font-size:9px;line-height:1;padding:5px 7px;border:1px solid rgba(255,255,255,.22);color:#ddd;background:rgba(255,255,255,.04);min-width:22px;text-align:center;}
.settings{display:flex;flex-direction:column;gap:20px;margin:26px 0;}
.setting{display:flex;align-items:center;gap:14px;font-family:var(--mono);font-size:9px;letter-spacing:.18em;color:#aeb4b8;}
.setting>span{width:130px;}
.setting input[type=range]{flex:1;-webkit-appearance:none;height:2px;background:rgba(255,255,255,.17);outline:none;}
.setting input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:10px;height:16px;background:var(--amber);cursor:pointer;}
.setting output{width:46px;text-align:right;color:var(--amber);}
.setting.toggle input{display:none;}
.setting.toggle i{width:38px;height:18px;border:1px solid rgba(255,255,255,.25);position:relative;margin-left:auto;cursor:pointer;}
.setting.toggle i:after{content:"";position:absolute;width:12px;height:12px;left:2px;top:2px;background:#71777c;transition:.16s;}
.setting.toggle input:checked+i:after{left:22px;background:var(--amber);box-shadow:0 0 8px rgba(242,174,85,.6);}
.pause-panel{width:min(440px,92vw);}
.pause-panel h2{font-size:46px;letter-spacing:.14em;margin-bottom:8px;}
.result-panel{width:min(620px,94vw);}
.result-panel h2{font-size:40px;}
.result-text{font-family:var(--mono);font-size:11px;line-height:1.7;color:#9aa1a7;margin:0 0 24px;}
.stats{display:grid;grid-template-columns:1fr 1fr 1fr;border-top:1px solid var(--line);border-left:1px solid var(--line);}
.stats>div{padding:14px;border-right:1px solid var(--line);border-bottom:1px solid var(--line);display:flex;flex-direction:column;gap:6px;}
.stats label{font-family:var(--mono);font-size:7px;letter-spacing:.2em;color:var(--faint);}
.stats b{font-family:var(--mono);font-size:17px;letter-spacing:.06em;}
.stats .stat-score b{color:var(--amber);}
.new-best{font-family:var(--mono);font-size:9px;letter-spacing:.28em;color:var(--amber);text-align:center;margin-top:18px;animation:pulse 1.8s infinite;}

/* ---------- HUD ---------- */
.hud{position:absolute;inset:0;z-index:20;pointer-events:none;font-family:var(--font);text-shadow:0 1px 4px rgba(0,0,0,.75);}
.hud-corner{position:absolute;width:26px;height:26px;border-color:rgba(255,255,255,.24);border-style:solid;}
.hud-corner.tl{top:18px;left:18px;border-width:1px 0 0 1px;}
.hud-corner.tr{top:18px;right:18px;border-width:1px 1px 0 0;}
.hud-corner.bl{bottom:18px;left:18px;border-width:0 0 1px 1px;}
.hud-corner.br{bottom:18px;right:18px;border-width:0 1px 1px 0;}
.hud-top-left{position:absolute;top:34px;left:38px;}
.mission-tag{font-family:var(--mono);font-size:9px;letter-spacing:.22em;color:#d8d9d7;display:flex;align-items:center;gap:7px;margin-bottom:14px;}
.mission-tag em{font-style:normal;color:var(--faint);}
.mission-dot{width:4px;height:4px;background:var(--amber);border-radius:50%;box-shadow:0 0 6px var(--amber);}
.radar-wrap{width:132px;height:132px;position:relative;}
#radar{width:132px;height:132px;display:block;opacity:.9;}
.radar-ring{position:absolute;inset:0;border:1px solid rgba(233,229,220,.1);border-radius:50%;pointer-events:none;}
.radar-ring:before{content:"";position:absolute;inset:18px;border:1px solid rgba(233,229,220,.07);border-radius:50%;}
.radar-label{font-family:var(--mono);font-size:7px;letter-spacing:.2em;color:#6c747b;margin-top:2px;text-align:center;}
.objective{font-family:var(--mono);font-size:8px;letter-spacing:.16em;color:var(--amber);margin-top:8px;max-width:180px;line-height:1.6;}
.hud-top-center{position:absolute;top:34px;left:50%;transform:translateX(-50%);text-align:center;min-width:260px;}
.wave-label{font-family:var(--mono);font-size:11px;letter-spacing:.28em;color:#a9afb4;}
.wave-label b{color:var(--ink);font-size:14px;}
.wave-label span{color:var(--faint);}
.wave-track{height:2px;background:rgba(255,255,255,.1);margin:8px auto 6px;width:220px;position:relative;overflow:hidden;}
#wave-progress{position:absolute;inset:0;width:20%;background:linear-gradient(90deg,rgba(242,174,85,.5),var(--amber));transition:width .6s ease;box-shadow:0 0 8px rgba(242,174,85,.5);}
.hostiles{font-family:var(--mono);font-size:8px;letter-spacing:.2em;color:#8a9198;}
.hostiles b{color:var(--amber);}
.hud-top-right{position:absolute;top:34px;right:38px;text-align:right;display:flex;flex-direction:column;align-items:flex-end;}
.score-block{display:flex;flex-direction:column;align-items:flex-end;gap:3px;}
.score-block label{font-family:var(--mono);font-size:7px;letter-spacing:.24em;color:var(--faint);}
.score-block span{font-family:var(--mono);font-size:19px;letter-spacing:.12em;color:#e6e6e1;}
.killfeed{display:flex;flex-direction:column;align-items:flex-end;gap:5px;margin-top:22px;max-width:330px;}
.killfeed .feed{font-family:var(--mono);font-size:9px;letter-spacing:.1em;padding:3px 7px;background:rgba(4,6,9,.6);border-right:1px solid rgba(242,174,85,.55);color:#c5c9ca;animation:feedin .2s ease;transition:opacity .4s,transform .4s;}
.killfeed .feed b{color:var(--amber);font-weight:600;}
.killfeed .feed.head b{color:var(--red);}
.killfeed .feed.out{opacity:0;transform:translateX(10px);}
@keyframes feedin{from{opacity:0;transform:translateX(12px)}to{opacity:1;transform:none}}
.hitmarker{position:absolute;left:50%;top:50%;width:28px;height:28px;transform:translate(-50%,-50%) scale(.9);opacity:0;transition:opacity .08s;}
.hitmarker.show{opacity:1;}
.hitmarker i{position:absolute;width:7px;height:1.5px;background:#fff;box-shadow:0 0 3px rgba(0,0,0,.9);}
.hitmarker i:nth-child(1){left:0;top:4px;transform:rotate(45deg);}
.hitmarker i:nth-child(2){right:0;top:4px;transform:rotate(-45deg);}
.hitmarker i:nth-child(3){left:0;bottom:4px;transform:rotate(-45deg);}
.hitmarker i:nth-child(4){right:0;bottom:4px;transform:rotate(45deg);}
.hitmarker.kill i{background:var(--red);width:10px;height:2px;}
.crosshair{position:absolute;left:50%;top:50%;width:42px;height:42px;transform:translate(-50%,-50%);transition:opacity .15s;}
.crosshair i{position:absolute;background:rgba(245,244,238,.9);box-shadow:0 0 2px rgba(0,0,0,.95);}
.crosshair .t{width:1.5px;height:7px;left:50%;top:0;margin-left:-.75px;}
.crosshair .b{width:1.5px;height:7px;left:50%;bottom:0;margin-left:-.75px;}
.crosshair .l{height:1.5px;width:7px;top:50%;left:0;margin-top:-.75px;}
.crosshair .r{height:1.5px;width:7px;top:50%;right:0;margin-top:-.75px;}
.crosshair .ch-dot{position:absolute;left:50%;top:50%;width:2px;height:2px;margin:-1px;border-radius:50%;background:var(--amber);box-shadow:0 0 4px rgba(242,174,85,.9);}
.crosshair.ads{opacity:.25;}
.damage-arrows{position:absolute;inset:0;}
.dmg-arrow{position:absolute;left:50%;top:50%;width:150px;height:150px;margin:-75px 0 0 -75px;transform:rotate(var(--rot));opacity:0;transition:opacity .25s;}
.dmg-arrow:before{content:"";position:absolute;left:50%;top:0;width:0;height:0;margin-left:-24px;border-left:24px solid transparent;border-right:24px solid transparent;border-bottom:15px solid rgba(255,58,44,.72);filter:blur(.3px);}
.dmg-arrow.show{opacity:1;}
.interact{position:absolute;left:50%;top:62%;transform:translateX(-50%);font-family:var(--mono);font-size:9px;letter-spacing:.22em;color:var(--amber);opacity:0;transition:.2s;}
.interact.show{opacity:1;}
.hud-bottom-left{position:absolute;bottom:38px;left:38px;width:264px;}
.vitals-label{font-family:var(--mono);font-size:8px;letter-spacing:.24em;color:#959ca2;margin-bottom:7px;display:flex;justify-content:space-between;}
.vitals-label span{color:var(--ink);font-size:10px;}
.health-track{height:5px;background:rgba(255,255,255,.12);position:relative;overflow:hidden;width:220px;}
#health-fill{position:absolute;inset:0;width:100%;background:linear-gradient(90deg,#d7d5c9,#f5f0e1);transition:width .2s ease;}
.health-track.low #health-fill{background:linear-gradient(90deg,#ff4a3d,#ff7a5c);box-shadow:0 0 12px rgba(255,58,44,.6);}
.health-seg{position:absolute;inset:0;background:repeating-linear-gradient(90deg,transparent 0 21px,rgba(5,7,10,.7) 21px 23px);pointer-events:none;}
.equip-row{display:flex;align-items:center;gap:10px;margin-top:13px;}
.equip-label{font-family:var(--mono);font-size:7px;letter-spacing:.18em;color:var(--faint);}
.grenades{display:flex;gap:4px;}
.grenades i{width:8px;height:13px;border:1px solid rgba(233,229,220,.4);border-radius:2px;display:block;}
.grenades i.full{background:var(--amber);border-color:var(--amber);box-shadow:0 0 6px rgba(242,174,85,.35);}
.hud-bottom-right{position:absolute;bottom:36px;right:38px;text-align:right;}
.weapon-row{display:flex;align-items:baseline;justify-content:flex-end;gap:14px;}
.weapon-name{font-size:23px;letter-spacing:.16em;font-weight:600;color:#e9e6dc;}
.weapon-mode{font-family:var(--mono);font-size:7px;letter-spacing:.18em;color:var(--faint);}
.ammo-row{font-family:var(--mono);display:flex;align-items:baseline;justify-content:flex-end;gap:7px;line-height:1;margin-top:2px;}
#ammo-mag{font-size:42px;letter-spacing:.02em;color:#f3efe2;text-shadow:0 2px 20px rgba(0,0,0,.8);}
.ammo-sep{color:var(--faint);font-size:17px;}
#ammo-reserve{font-size:17px;color:#9aa0a5;}
.ammo-row.empty #ammo-mag{color:var(--red);}
.reload-track{height:1.5px;width:170px;background:rgba(255,255,255,.12);margin:7px 0 8px auto;position:relative;overflow:hidden;}
#reload-fill{position:absolute;left:0;top:0;bottom:0;width:0;background:var(--amber);}
.weapon-slots{display:flex;gap:14px;justify-content:flex-end;font-family:var(--mono);font-size:7px;letter-spacing:.13em;color:#555d64;}
.weapon-slots .slot.active{color:var(--amber);}
.hint{position:absolute;left:50%;bottom:22%;transform:translateX(-50%);font-family:var(--mono);font-size:9px;letter-spacing:.2em;color:#b9bec2;background:rgba(4,6,9,.55);padding:6px 12px;opacity:0;transition:.2s;white-space:nowrap;}
.hint.show{opacity:1;}
.wave-banner{position:absolute;left:0;right:0;top:27%;text-align:center;opacity:0;transition:opacity .5s;pointer-events:none;}
.wave-banner.show{opacity:1;}
.wave-banner .eyebrow{justify-content:center;margin-bottom:10px;}
.wave-banner .big{font-size:64px;letter-spacing:.2em;font-weight:800;line-height:.9;color:#f4f0e6;text-shadow:0 0 40px rgba(0,0,0,.7);}
.wave-banner .big em{font-style:normal;color:var(--amber);}
.wave-banner .sub{font-family:var(--mono);font-size:9px;letter-spacing:.36em;color:#c0c4c5;margin-top:13px;}
.notice{position:absolute;left:50%;top:20%;transform:translateX(-50%);font-family:var(--mono);font-size:9px;letter-spacing:.2em;color:var(--amber);background:rgba(4,6,9,.5);border:1px solid rgba(242,174,85,.3);padding:6px 14px;opacity:0;transition:.25s;}
.notice.show{opacity:1;}
.subtitle{position:absolute;left:50%;bottom:15%;transform:translateX(-50%);font-family:var(--mono);font-size:10px;letter-spacing:.12em;color:#d7d9d8;text-align:center;max-width:560px;opacity:0;transition:.3s;background:rgba(4,6,9,.35);padding:6px 12px;}
.subtitle.show{opacity:1;}
.hud-bottom-center{position:absolute;bottom:38px;left:50%;transform:translateX(-50%);text-align:center;}
.compass{display:flex;gap:26px;font-family:var(--mono);font-size:8px;letter-spacing:.1em;color:#7b8389;}
.compass span:first-child{color:var(--ink);}
.compass-tick{width:1px;height:7px;background:var(--amber);margin:4px auto 0;box-shadow:0 0 4px var(--amber);}
.damage-vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at center,transparent 38%,rgba(150,14,8,.44) 100%);opacity:0;transition:opacity .18s;}
.low-health{position:absolute;inset:0;pointer-events:none;box-shadow:inset 0 0 110px 20px rgba(190,20,10,.35);opacity:0;}
.low-health.on{animation:heartbeat 1.1s ease-in-out infinite;}
@keyframes heartbeat{0%,100%{opacity:.25}45%{opacity:.85}}
#ammo-mag,#health-num,#score{font-variant-numeric:tabular-nums;}

/* ---------- touch ---------- */
.touch-controls{position:absolute;inset:0;z-index:25;pointer-events:none;}
.stick-zone{position:absolute;left:calc(14px + env(safe-area-inset-left));bottom:calc(14px + env(safe-area-inset-bottom));width:148px;height:148px;pointer-events:auto;touch-action:none;}
.stick-base{position:absolute;inset:12px;border:1px solid rgba(255,255,255,.22);border-radius:50%;background:rgba(5,7,10,.25);backdrop-filter:blur(2px);}
.stick-base:before,.stick-base:after{content:"";position:absolute;background:rgba(255,255,255,.1);}
.stick-base:before{left:50%;top:16%;bottom:16%;width:1px;}
.stick-base:after{top:50%;left:16%;right:16%;height:1px;}
.stick-knob{position:absolute;left:50%;top:50%;width:54px;height:54px;margin:-27px;border-radius:50%;background:rgba(242,174,85,.2);border:1px solid rgba(242,174,85,.7);box-shadow:0 0 22px rgba(242,174,85,.15);}
.look-zone{position:absolute;right:0;top:12%;bottom:0;width:55%;pointer-events:auto;touch-action:none;}
.touch-buttons{position:absolute;right:calc(16px + env(safe-area-inset-right));bottom:calc(16px + env(safe-area-inset-bottom));display:flex;flex-direction:column;align-items:flex-end;gap:10px;pointer-events:none;}
.t-btn{pointer-events:auto;touch-action:none;border:1px solid rgba(255,255,255,.25);background:rgba(8,11,15,.45);color:#e6e3da;font-family:var(--mono);font-size:9px;letter-spacing:.12em;backdrop-filter:blur(3px);}
.t-btn:active,.t-btn.on{background:rgba(242,174,85,.28);border-color:var(--amber);color:#fff;}
.t-fire{width:78px;height:78px;border-radius:50%;font-size:11px;}
.t-aim{width:58px;height:58px;border-radius:50%;}
.t-small{width:44px;height:44px;border-radius:50%;font-size:8px;}
.rotate-hint{position:absolute;top:calc(10px + env(safe-area-inset-top));left:50%;transform:translateX(-50%);font-family:var(--mono);font-size:7px;letter-spacing:.16em;color:#7e858b;opacity:.6;}
.rotate-screen{background:#05070a;z-index:200;align-items:center;justify-content:center;text-align:center;}
.rotate-icon{font-size:50px;color:var(--amber);transform:rotate(90deg);margin-bottom:20px;}
.rotate-screen h2{font-size:24px;letter-spacing:.2em;}
.rotate-screen p{font-family:var(--mono);font-size:10px;color:var(--dim);letter-spacing:.1em;}

@media (max-width:900px){
  .menu-side{display:none;}
  .menu-main{padding:0 7vw;max-width:none;}
  .menu-top{padding:18px 22px;font-size:8px;}
  .menu-top .dim,.menu-top-right span:last-child{display:none;}
  .menu-footer{padding:14px 22px;}
  .warn{font-size:7px;}
  .menu-meta{gap:22px;flex-wrap:wrap;margin-top:24px;}
  .brief-grid{grid-template-columns:1fr;gap:18px;}
  .panel.wide-panel{max-height:92vh;overflow:auto;}
  .title{font-size:clamp(64px,16vw,120px);}
  .menu-blurb{font-size:11px;margin-bottom:22px;}
  .hud-bottom-left{bottom:calc(20px + env(safe-area-inset-bottom));left:calc(16px + env(safe-area-inset-left));width:190px;}
  .hud-bottom-right{bottom:calc(20px + env(safe-area-inset-bottom));right:calc(16px + env(safe-area-inset-right));}
  .hud-bottom-center{display:none;}
  .hud-top-left{top:calc(16px + env(safe-area-inset-top));left:calc(16px + env(safe-area-inset-left));}
  .hud-top-right{top:calc(16px + env(safe-area-inset-top));right:calc(16px + env(safe-area-inset-right));}
  .hud-top-center{top:calc(14px + env(safe-area-inset-top));min-width:160px;}
  .radar-wrap{width:96px;height:96px;}
  #radar{width:96px;height:96px;}
  .mission-tag{font-size:7px;margin-bottom:8px;}
  .objective{font-size:7px;max-width:130px;}
  .health-track{width:150px;}
  .weapon-name{font-size:16px;}
  #ammo-mag{font-size:32px;}
  .weapon-slots{display:none;}
  .wave-label{font-size:9px;}
  .wave-track{width:140px;}
  .hostiles{font-size:7px;}
  .killfeed .feed{font-size:8px;}
  .stats{grid-template-columns:1fr 1fr;}
  .panel{padding:22px;}
  .panel h2{font-size:26px;}
  .control-grid{grid-template-columns:1fr;}
  .menu-hint{display:none;}
  .hud-bottom-left .equip-row{margin-top:8px;}
}
@media (max-width:600px){
  .menu-main{padding:0 24px;}
  .eyebrow{font-size:7px;}
  .title-rule i{font-size:9px;}
  .menu-meta span{font-size:9px;}
  .menu-meta label{font-size:7px;}
  .menu-footer .warn{max-width:70%;line-height:1.5;}
}
@media (max-height:520px) and (orientation:landscape){
  .menu-main{transform:none;}
  .title{font-size:64px;}
  .menu-blurb{display:none;}
  .menu-meta{display:none;}
  .menu-actions{max-width:310px;}
  .title-rule{margin:12px 0 14px;}
  .menu-top{padding:10px 22px;}
  .menu-footer{padding:8px 22px;}
  .btn{padding:9px 14px;font-size:11px;}
  .hud-top-left,.hud-top-right,.hud-top-center{top:12px;}
  .hud-bottom-left,.hud-bottom-right{bottom:14px;}
}

// Procedural WebAudio sound system. No external assets.
export class AudioSystem {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.sfx = null;
    this.ambient = null;
    this.volume = 0.8;
    this.enabled = true;
    this.started = false;
    this.stepTimer = 0;
    this._lastThunder = 0;
  }

  init() {
    if (this.ctx) return;
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) { this.enabled = false; return; }
    this.ctx = new AC();
    const c = this.ctx;
    this.master = c.createGain();
    this.master.gain.value = this.volume;
    const comp = c.createDynamicsCompressor();
    comp.threshold.value = -14; comp.knee.value = 22; comp.ratio.value = 5;
    comp.attack.value = 0.003; comp.release.value = 0.24;
    this.master.connect(comp).connect(c.destination);

    this.sfx = c.createGain(); this.sfx.gain.value = 0.9; this.sfx.connect(this.master);
    this.ambient = c.createGain(); this.ambient.gain.value = 0.5; this.ambient.connect(this.master);

    // Reverb impulse: dark concrete courtyard.
    this.reverb = c.createConvolver();
    const len = Math.floor(c.sampleRate * 2.4);
    const imp = c.createBuffer(2, len, c.sampleRate);
    for (let ch = 0; ch < 2; ch++) {
      const d = imp.getChannelData(ch);
      for (let i = 0; i < len; i++) {
        const t = i / len;
        d[i] = (Math.random() * 2 - 1) * Math.pow(1 - t, 2.6) * (0.6 + 0.4 * Math.sin(i * 0.0007));
      }
    }
    this.reverb.buffer = imp;
    this.reverbGain = c.createGain(); this.reverbGain.gain.value = 0.42;
    this.reverb.connect(this.reverbGain).connect(this.master);

