    };
    barrel(-7.6, 13.5); barrel(-7.0, 14.2, barrelMats[1]); barrel(-7.9, 14.7, barrelMats[2]);
    barrel(19.2, -15.3, barrelMats[1]); barrel(19.9, -15.9, barrelMats[0]);
    barrel(-24.4, 7.5, barrelMats[0], true); barrel(-23.6, 8.2);
    barrel(22.8, 20.6, barrelMats[2]); barrel(9.0, 13.4, barrelMats[1]);
    // pallet stacks
    for (const [x, z, rot] of [[-21.5, 21.5, 0.2], [15.5, 23, -0.3], [-15.5, 12.5, 0]]) {
      for (let i = 0; i < 3; i++) {
        const p = this.box(1.5, 0.09, 1.1, x, 0.12 + i * 0.15, z, matWood, { rot, collide: false });
        p.receiveShadow = true;
      }
      this.addCollider(x, z, 1.5, 1.1, 0.5);
    }
    // cones
    const coneMat = new THREE.MeshStandardMaterial({ color: 0x8a3c18, roughness: 0.8 });
    const cone = (x, z) => {
      const c = new THREE.Mesh(new THREE.ConeGeometry(0.18, 0.55, 8), coneMat); c.position.set(x, 0.28, z); this.scene.add(c);
      const band = new THREE.Mesh(new THREE.CylinderGeometry(0.13, 0.16, 0.05, 8), new THREE.MeshStandardMaterial({ color: 0xcfd3d1, emissive: 0x333333 })); band.position.set(x, 0.32, z); this.scene.add(band);
    };
    cone(2, 10); cone(-1.4, 12.5); cone(12, -4); cone(-15, 5);
    // generator cables on ground
    const cableMat = new THREE.MeshBasicMaterial({ color: 0x0a0c0d });
    const pts = [new THREE.Vector3(24, 0.04, 10.5), new THREE.Vector3(18, 0.04, 8), new THREE.Vector3(12, 0.04, 6), new THREE.Vector3(8, 0.04, 3)];
    const cg = new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts), 30, 0.04, 4, false), cableMat); this.scene.add(cg);
    // ammo / supply crates
    for (const [x, z, rot] of [[-1.5, 15.5, 0.1], [16.5, 8.2, -0.2]]) {
      const ammo = this.box(0.9, 0.45, 0.55, x, 0.225, z, new THREE.MeshStandardMaterial({ color: 0x34452e, roughness: 0.7, metalness: 0.3 }), { rot, collide: true });
      const stripe = new THREE.Mesh(new THREE.PlaneGeometry(0.6, 0.08), new THREE.MeshBasicMaterial({ color: 0xc6a248 }));
      stripe.position.set(x, 0.35, z + 0.29); stripe.rotation.y = rot; this.scene.add(stripe);
      ammo.castShadow = true;
    }
  }

  buildDistant() {
    // Silhouetted industrial skyline beyond the walls.
    const mat = new THREE.MeshStandardMaterial({ color: 0x0b1017, roughness: 1, metalness: 0 });
    for (let i = 0; i < 26; i++) {
      const a = (i / 26) * Math.PI * 2 + rand(-0.1, 0.1);
      const r = rand(48, 85);
      const w = rand(6, 18), h = rand(4, 28), d = rand(4, 12);
      const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
      m.position.set(Math.cos(a) * r, h / 2 - 2, Math.sin(a) * r);
      m.rotation.y = rand(0, 3);
      this.scene.add(m);
      // sparse window lights
      if (Math.random() > 0.45) {
        for (let k = 0; k < 3; k++) {
          const p = new THREE.Mesh(new THREE.PlaneGeometry(0.35, 0.25), new THREE.MeshBasicMaterial({ color: Math.random() > 0.5 ? 0xe0a45b : 0x6fa6d8 }));
          p.position.set(0, rand(-h / 2 + 2, h / 2 - 2), d / 2 + 0.01); m.add(p);
        }
      }
    }
    // cranes
    for (const [x, z] of [[55, -40], [-60, -55], [70, 30]]) {
      const g = new THREE.Group(); g.position.set(x, 0, z);
      const mast = new THREE.Mesh(new THREE.BoxGeometry(1.4, 36, 1.4), mat); mast.position.y = 18; g.add(mast);
      const arm = new THREE.Mesh(new THREE.BoxGeometry(28, 1, 1), mat); arm.position.set(8, 34, 0); g.add(arm);
      const cab = new THREE.Mesh(new THREE.BoxGeometry(3, 2.5, 2.5), mat); cab.position.set(-1, 33, 0); g.add(cab);
      const red = new THREE.Mesh(new THREE.SphereGeometry(0.22, 6, 5), new THREE.MeshBasicMaterial({ color: 0xff3524 })); red.position.set(0, 36.3, 0); g.add(red);
      this.scene.add(g);
    }
    // distant hills
    const hillMat = new THREE.MeshStandardMaterial({ color: 0x070b10, roughness: 1, flatShading: true });
    for (let i = 0; i < 7; i++) {
      const a = rand(0, Math.PI * 2), r = rand(110, 165);
      const hill = new THREE.Mesh(new THREE.ConeGeometry(rand(30, 70), rand(15, 40), 5), hillMat);
      hill.position.set(Math.cos(a) * r, -5, Math.sin(a) * r); this.scene.add(hill);
    }
  }

  buildRain() {
    const n = 1500;
    const pos = new Float32Array(n * 6);
    const data = [];
    for (let i = 0; i < n; i++) {
      const x = rand(-35, 35), y = rand(0, 26), z = rand(-35, 35);
      const len = rand(0.35, 1.1);
      data.push({ x, y, z, len, speed: rand(20, 34) });
      pos.set([x, y, z, x + 0.08, y - len, z + 0.02], i * 6);
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    const m = new THREE.LineBasicMaterial({ color: 0x9bb1c8, transparent: true, opacity: 0.22, depthWrite: false, blending: THREE.AdditiveBlending, fog: true });
    this.rain = new THREE.LineSegments(g, m);
    this.rain.frustumCulled = false;
    this.rainData = data;
    this.rainPos = pos;
    this.scene.add(this.rain);
    // splashes: tiny bright rings on the ground near player
    const sn = 90, sp = new Float32Array(sn * 3);
    this.splashData = [];
    for (let i = 0; i < sn; i++) {
      this.splashData.push({ x: rand(-15, 15), y: 0.03, z: rand(-15, 15), life: Math.random(), speed: rand(1.5, 3.5) });
    }
    const sg = new THREE.BufferGeometry(); sg.setAttribute('position', new THREE.BufferAttribute(sp, 3));
    this.splashes = new THREE.Points(sg, new THREE.PointsMaterial({ color: 0xbcd2e8, size: 0.055, transparent: true, opacity: 0.4, depthWrite: false, blending: THREE.AdditiveBlending }));
    this.splashes.frustumCulled = false;
    this.splashPos = sp;
    this.scene.add(this.splashes);
  }

  buildMist() {
    for (let i = 0; i < 16; i++) {
      const sp = new THREE.Sprite(new THREE.SpriteMaterial({ map: TEX.smoke, transparent: true, opacity: rand(0.05, 0.11), depthWrite: false, color: 0x9aacba }));
      sp.position.set(rand(-26, 26), rand(0.3, 1.6), rand(-26, 26));
      const s = rand(8, 18); sp.scale.set(s, s * 0.35, 1);
      this.scene.add(sp);
      this.smokePuffs.push({ sprite: sp, baseY: sp.position.y, phase: rand(0, 6), speed: rand(0.05, 0.15), baseScale: s, mist: true });
    }
  }

  triggerLightning() {
    this.flash = 1;
    this.lightningTimer = rand(16, 32);
  }

  update(dt, camera) {
    this.time += dt;
    const t = this.time;

    // lightning
    this.lightningTimer -= dt;
    if (this.lightningTimer <= 0) this.triggerLightning();
    if (this.flash > 0) {
      this.flash = Math.max(0, this.flash - dt * 3.3);
      const f = this.flash * (0.6 + Math.random() * 0.4);
      this.hemi.intensity = 0.72 + f * 7;
      this.moonLight.intensity = 0.85 + f * 3;
      this.sky.material.uniforms.flash.value = f;
    } else {
      this.hemi.intensity = 0.72; this.moonLight.intensity = 0.85; this.sky.material.uniforms.flash.value = 0;
    }

    // flicker lights
    for (const f of this.flickerLights) {
      if (f.beacon) f.light.intensity = f.base * (0.25 + 0.75 * Math.pow(Math.max(0, Math.sin(t * 3.1 + f.seed)), 8));
      else if (f.flicker) {
        const n = Math.sin(t * 17 + f.seed) * Math.sin(t * 7.3 + f.seed * 2) * Math.sin(t * 2.1);
        f.light.intensity = f.base * (0.82 + 0.18 * n) * (Math.sin(t * 0.7 + f.seed) > -0.92 ? 1 : 0.15);
      }
    }
    if (this.uplinkLight) this.uplinkLight.intensity = 5 + Math.sin(t * 2.4) * 1.5;

    // searchlights
    for (const s of this.searchlights) {
      const a = t * 0.12 + s.phase;
      const tx = Math.sin(a) * 22, tz = Math.cos(a * 0.8) * 22;
      s.target = s.spot.target;
      s.spot.target.position.set(tx, 0, tz);
      const dir = new THREE.Vector3(tx - s.x, 0 - 9, tz - s.z).normalize();
      s.pivot.lookAt(tx, 0, tz);
    }

    // rain relative to camera
    if (this.rainData && camera) {
      const cx = camera.position.x, cz = camera.position.z;
      for (let i = 0; i < this.rainData.length; i++) {
        const d = this.rainData[i];
        d.y -= d.speed * dt;
        if (d.y < 0) {
          d.y = rand(18, 30); d.x = cx + rand(-32, 32); d.z = cz + rand(-32, 32);
        }
        const o = i * 6;
        this.rainPos[o] = d.x; this.rainPos[o + 1] = d.y; this.rainPos[o + 2] = d.z;
        this.rainPos[o + 3] = d.x + 0.07; this.rainPos[o + 4] = d.y - d.len; this.rainPos[o + 5] = d.z + 0.02;
      }
      this.rain.geometry.attributes.position.needsUpdate = true;

      // splashes near player
      for (let i = 0; i < this.splashData.length; i++) {
        const s = this.splashData[i];
        s.life -= dt * s.speed;
        if (s.life <= 0) { s.life = 1; s.x = cx + rand(-18, 18); s.z = cz + rand(-18, 18); }
        const o = i * 3;
        this.splashPos[o] = s.x; this.splashPos[o + 1] = 0.025 + (1 - s.life) * 0.04; this.splashPos[o + 2] = s.z;
      }
      this.splashes.geometry.attributes.position.needsUpdate = true;
    }

    // dust drift
    if (this.dust) this.dust.rotation.y += dt * 0.006;

    // embers
    if (this.embers) {
      const p = this.emberGeo.attributes.position;
      for (let i = 0; i < p.count; i++) {
        let y = p.getY(i) + dt * (0.25 + (i % 5) * 0.08);
        if (y > 9) y = 0.2;
        p.setY(i, y);
        p.setX(i, p.getX(i) + Math.sin(t * 0.5 + i) * dt * 0.06);
      }
      p.needsUpdate = true;
    }

    // smoke and mist
    for (const s of this.smokePuffs) {
      const y = s.baseY + (s.mist ? Math.sin(t * 0.2 + s.phase) * 0.3 : ((t * s.speed + s.phase) % 4));
      s.sprite.position.y = s.mist ? y : s.baseY + ((t * s.speed + s.phase) % 4.5);
      if (!s.mist) s.sprite.material.opacity = 0.2 * (1 - ((t * s.speed + s.phase) % 4.5) / 4.5);
    }

    // beacon pulse
    for (let i = 0; i < this.beacons.length; i++) {
      const b = this.beacons[i];
      if (b.material && b.material.emissiveIntensity !== undefined) b.material.emissiveIntensity = 1.6 + Math.sin(t * 3.4 + i) * 1.6;
    }
  }

  // ray vs level AABBs
  raycast(origin, dir, maxDist = 200) {
    let best = maxDist, hit = null;
    for (const c of this.colliders) {
      const b = this.rayBox(origin, dir, c.x1, 0, c.z1, c.x2, c.h, c.z2);
      if (b !== null && b < best) { best = b; hit = c; }
    }
    // ground
    if (dir.y < -0.0001) {
      const t = -origin.y / dir.y;
      if (t > 0.01 && t < best) { best = t; hit = 'ground'; }
    }
    if (!hit) return null;
    return { distance: best, point: origin.clone().addScaledVector(dir, best), collider: hit };
  }

  rayBox(o, d, x1, y1, z1, x2, y2, z2) {
    let tmin = 0, tmax = 1e9;
    for (const [oo, dd, mn, mx] of [[o.x, d.x, x1, x2], [o.y, d.y, y1, y2], [o.z, d.z, z1, z2]]) {
      if (Math.abs(dd) < 1e-8) { if (oo < mn || oo > mx) return null; }
      else {
        let t1 = (mn - oo) / dd, t2 = (mx - oo) / dd;
        if (t1 > t2) { const tt = t1; t1 = t2; t2 = tt; }
        tmin = Math.max(tmin, t1); tmax = Math.min(tmax, t2);
        if (tmin > tmax) return null;
      }
    }
    return tmin > 0.001 ? tmin : (tmax > 0.001 ? tmax : null);
  }

  // simple line of sight check between two world points
  hasLOS(a, b) {
    const dir = b.clone().sub(a);
    const dist = dir.length(); if (dist < 0.001) return true;
    dir.divideScalar(dist);
    for (const c of this.colliders) {
      if (c.h < 1.2) continue;
      const t = this.rayBox(a, dir, c.x1, 0, c.z1, c.x2, c.h, c.z2);
      if (t !== null && t < dist - 0.3) return false;
    }
    return true;
  }

  // collide circle with AABB and resolve
  collide(pos, radius, height = 1.8) {
    let hit = false;
    for (const c of this.colliders) {
      if (c.h < 0.4) continue;
      const nx = Math.max(c.x1, Math.min(pos.x, c.x2));
      const nz = Math.max(c.z1, Math.min(pos.z, c.z2));
      let dx = pos.x - nx, dz = pos.z - nz;
      let d2 = dx * dx + dz * dz;
      if (d2 < radius * radius) {
        if (d2 < 0.00001) {
          // inside: push toward nearest edge
          const l = pos.x - c.x1, r = c.x2 - pos.x, t = pos.z - c.z1, b = c.z2 - pos.z;
          const m = Math.min(l, r, t, b);
          if (m === l) pos.x = c.x1 - radius; else if (m === r) pos.x = c.x2 + radius;
          else if (m === t) pos.z = c.z1 - radius; else pos.z = c.z2 + radius;
        } else {
          const d = Math.sqrt(d2);
          pos.x += (dx / d) * (radius - d);
          pos.z += (dz / d) * (radius - d);
        }
        hit = true;
      }
    }
    return hit;
  }
}

import * as THREE from 'three';

const rand = (a, b) => a + Math.random() * (b - a);

function glowTexture(inner = 'rgba(255,255,255,1)', mid = 'rgba(255,190,110,.55)', outer = 'rgba(255,120,30,0)') {
  const c = document.createElement('canvas'); c.width = c.height = 128;
  const x = c.getContext('2d');
  const g = x.createRadialGradient(64, 64, 0, 64, 64, 64);
  g.addColorStop(0, inner); g.addColorStop(0.25, mid); g.addColorStop(1, outer);
  x.fillStyle = g; x.fillRect(0, 0, 128, 128);
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; return t;
}

export class Effects {
  constructor(scene, camera, audio) {
    this.scene = scene;
    this.camera = camera;
    this.audio = audio;
    this.tracers = [];
    this.decals = [];
    this.flashes = [];
    this.shells = [];
    this.smoke = [];
    this.rings = [];
    this.time = 0;
    this.tracerPool = [];
    this.glow = glowTexture();
    this.smokeTex = (() => {
      const c = document.createElement('canvas'); c.width = c.height = 128;
      const x = c.getContext('2d');
      for (let i = 0; i < 18; i++) {
        const g = x.createRadialGradient(rand(30, 98), rand(30, 98), 0, 64, 64, rand(24, 60));
        g.addColorStop(0, 'rgba(190,195,200,.1)'); g.addColorStop(1, 'rgba(120,125,130,0)');
        x.fillStyle = g; x.fillRect(0, 0, 128, 128);
      }
      const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; return t;
    })();

    this.initSparks();
    this.initBlood();
    this.initShells();
    this.initSmokePool();
  }

  initSparks() {
    this.sparkCount = 500;
    const pos = new Float32Array(this.sparkCount * 3);
    const col = new Float32Array(this.sparkCount * 3);
    pos.fill(-9999);
    this.sparkGeo = new THREE.BufferGeometry();
    this.sparkGeo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    this.sparkGeo.setAttribute('color', new THREE.BufferAttribute(col, 3));
    this.sparkMat = new THREE.PointsMaterial({ size: 0.055, vertexColors: true, transparent: true, opacity: 0.95, depthWrite: false, blending: THREE.AdditiveBlending, sizeAttenuation: true });
    this.sparks = new THREE.Points(this.sparkGeo, this.sparkMat);
    this.sparks.frustumCulled = false;
    this.scene.add(this.sparks);
    this.sparkData = Array.from({ length: this.sparkCount }, () => ({ life: 0, vx: 0, vy: 0, vz: 0 }));
    this.sparkCursor = 0;
  }

  initBlood() {
    this.bloodCount = 260;
    const pos = new Float32Array(this.bloodCount * 3); pos.fill(-9999);
    this.bloodGeo = new THREE.BufferGeometry(); this.bloodGeo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
    this.bloodMat = new THREE.PointsMaterial({ color: 0x6b0d0a, size: 0.075, transparent: true, opacity: 0.85, depthWrite: false, sizeAttenuation: true });
    this.blood = new THREE.Points(this.bloodGeo, this.bloodMat); this.blood.frustumCulled = false;
    this.scene.add(this.blood);
    this.bloodData = Array.from({ length: this.bloodCount }, () => ({ life: 0, vx: 0, vy: 0, vz: 0 }));
    this.bloodCursor = 0;
  }

  initShells() {
    const geo = new THREE.CylinderGeometry(0.012, 0.014, 0.05, 5);
    const mat = new THREE.MeshStandardMaterial({ color: 0xb08d3e, metalness: 0.9, roughness: 0.3, emissive: 0x221100 });
    for (let i = 0; i < 28; i++) {
      const m = new THREE.Mesh(geo, mat); m.visible = false; m.castShadow = false;
      this.scene.add(m); this.shells.push({ mesh: m, life: 0, vx: 0, vy: 0, vz: 0, spin: new THREE.Vector3() });
    }
    this.shellCursor = 0;
  }

  initSmokePool() {
    for (let i = 0; i < 34; i++) {
      const s = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.smokeTex, transparent: true, opacity: 0, depthWrite: false, color: 0x8f979e }));
      s.visible = false; this.scene.add(s);
      this.smoke.push({ sprite: s, life: 0, max: 0, vy: 0, scale: 1, grow: 1 });
    }
    this.smokeCursor = 0;
  }

  spawnSparks(point, normal, count = 9, color = 0xffb260, speed = 5) {
    const p = this.sparkGeo.attributes.position, c = this.sparkGeo.attributes.color;
    const col = new THREE.Color(color);
    for (let k = 0; k < count; k++) {
      const i = this.sparkCursor; this.sparkCursor = (this.sparkCursor + 1) % this.sparkCount;
      const d = new THREE.Vector3(normal.x + rand(-0.8, 0.8), normal.y + rand(-0.4, 1.0), normal.z + rand(-0.8, 0.8)).normalize();
      const v = speed * rand(0.35, 1.35);
      const data = this.sparkData[i];
      data.life = rand(0.2, 0.62); data.max = data.life;
      data.vx = d.x * v; data.vy = d.y * v; data.vz = d.z * v;
      p.setXYZ(i, point.x, point.y, point.z);
      c.setXYZ(i, col.r, col.g, col.b);
    }
    p.needsUpdate = true; c.needsUpdate = true;
  }

  spawnBlood(point, dir, count = 7) {
    const p = this.bloodGeo.attributes.position;
    for (let k = 0; k < count; k++) {
      const i = this.bloodCursor; this.bloodCursor = (this.bloodCursor + 1) % this.bloodCount;
      const d = new THREE.Vector3(dir.x + rand(-0.6, 0.6), rand(-0.1, 0.8), dir.z + rand(-0.6, 0.6)).normalize();
      const data = this.bloodData[i];
      data.life = rand(0.25, 0.6); data.max = data.life;
      data.vx = d.x * rand(1, 4); data.vy = d.y * rand(1, 4); data.vz = d.z * rand(1, 4);
      p.setXYZ(i, point.x, point.y, point.z);
    }
    p.needsUpdate = true;
  }

  tracer(from, to, color = 0xffd9a0, width = 1) {
    let t = this.tracerPool.find(o => !o.active);
    if (!t) {
      const geo = new THREE.BufferGeometry();
      geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(6), 3));
      const mat = new THREE.LineBasicMaterial({ color, transparent: true, opacity: 1, blending: THREE.AdditiveBlending, depthWrite: false });
      const line = new THREE.Line(geo, mat); line.frustumCulled = false; this.scene.add(line);
      t = { line, active: false, life: 0, max: 1 }; this.tracerPool.push(t);
    }
    t.active = true; t.life = 0.075; t.max = 0.075; t.line.visible = true;
    t.line.material.color.setHex(color); t.line.material.opacity = 0.95;
    const a = t.line.geometry.attributes.position;
    a.setXYZ(0, from.x, from.y, from.z); a.setXYZ(1, to.x, to.y, to.z); a.needsUpdate = true;
    // bright head glow
    this.spawnSparks(to, new THREE.Vector3(0, 1, 0), 1, 0xffe4b0, 0.2);
  }

  muzzleFlash(pos, dir, scale = 1, color = 0xffc47a) {
    const sp = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.glow, color, transparent: true, opacity: 1, depthWrite: false, blending: THREE.AdditiveBlending }));
    sp.position.copy(pos); sp.scale.setScalar(rand(0.35, 0.55) * scale); this.scene.add(sp);
    const light = new THREE.PointLight(color, 14 * scale, 7 * scale, 2);
    light.position.copy(pos); this.scene.add(light);
    this.flashes.push({ sprite: sp, light, life: 0.055, max: 0.055 });
    // small smoke wisp
    this.spawnSmoke(pos, dir, 0.4, 0.35, 0.8);
  }

  spawnSmoke(pos, dir, scale = 1, life = 0.8, opacity = 0.3) {
    const s = this.smoke[this.smokeCursor]; this.smokeCursor = (this.smokeCursor + 1) % this.smoke.length;
    s.sprite.visible = true; s.sprite.position.copy(pos).addScaledVector(dir, 0.1);
    s.life = life; s.max = life; s.vy = rand(0.2, 0.6); s.scale = scale * rand(0.7, 1.2); s.grow = rand(1.6, 2.8);
    s.opacity = opacity;
    s.sprite.scale.setScalar(s.scale); s.sprite.material.opacity = opacity;
  }

  impact(point, normal, materialType = 'concrete') {
    const color = materialType === 'metal' ? 0xffd68a : materialType === 'wood' ? 0xd5a46a : 0xffb063;
    this.spawnSparks(point, normal, materialType === 'metal' ? 14 : 8, color, materialType === 'metal' ? 7 : 4.5);
    this.spawnSmoke(point, normal, rand(0.3, 0.6), rand(0.4, 0.9), 0.22);
    this.spawnDecal(point, normal);
    this.audio?.impact?.(materialType);
  }

  spawnDecal(point, normal) {
    let d = this.decals.find(o => !o.active);
    if (!d) {
      if (this.decals.length > 70) { d = this.decals.shift(); }
      else {
        const mesh = new THREE.Mesh(new THREE.CircleGeometry(0.09, 8), new THREE.MeshBasicMaterial({ map: this.glow, color: 0x090909, transparent: true, opacity: 0.85, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -2 }));
        this.scene.add(mesh); d = { mesh, active: false, life: 0 };
      }
    }
    d.active = true; d.life = 30;
    d.mesh.visible = true; d.mesh.material.opacity = 0.55;
    d.mesh.position.copy(point).addScaledVector(normal, 0.012);
    d.mesh.lookAt(point.clone().add(normal));
    d.mesh.rotateZ(rand(0, Math.PI * 2));
    d.mesh.scale.setScalar(rand(0.6, 1.35));
    this.decals.push(d);
  }

  shell(pos, dir) {
    const s = this.shells[this.shellCursor]; this.shellCursor = (this.shellCursor + 1) % this.shells.length;
    s.life = 1.6; s.mesh.visible = true; s.mesh.position.copy(pos);
    s.mesh.rotation.set(rand(0, 6), rand(0, 6), rand(0, 6));
    s.vx = dir.x * rand(0.8, 2) + rand(-0.6, 0.6);
    s.vy = rand(1.2, 2.6);
    s.vz = dir.z * rand(0.8, 2) + rand(-0.6, 0.6);
    s.spin.set(rand(-14, 14), rand(-14, 14), rand(-14, 14));
    s.bounced = false;
  }

  explosion(point, radius = 7) {
    const sphere = new THREE.Mesh(new THREE.SphereGeometry(1, 16, 12), new THREE.MeshBasicMaterial({ color: 0xffcf8a, transparent: true, opacity: 0.95, blending: THREE.AdditiveBlending, depthWrite: false }));
    sphere.position.copy(point); this.scene.add(sphere);
    const ring = new THREE.Mesh(new THREE.RingGeometry(0.6, 1, 32), new THREE.MeshBasicMaterial({ color: 0xffa45a, transparent: true, opacity: 0.8, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false }));
    ring.position.copy(point); ring.rotation.x = -Math.PI / 2; this.scene.add(ring);
    const light = new THREE.PointLight(0xffa24a, 90, radius * 4, 2); light.position.copy(point).add(new THREE.Vector3(0, 1, 0)); this.scene.add(light);
    this.flashes.push({ sphere, ring, light, life: 0.55, max: 0.55, explosion: true });
    for (let i = 0; i < 55; i++) {
      const n = new THREE.Vector3(rand(-1, 1), rand(-0.2, 1), rand(-1, 1)).normalize();
      const p = point.clone().addScaledVector(n, rand(0.2, 1.2));
      this.spawnSparks(p, n, 1, i % 3 === 0 ? 0xffe0a0 : 0xff7b2e, rand(9, 22));
    }
    for (let i = 0; i < 8; i++) {
      this.spawnSmoke(point.clone().add(new THREE.Vector3(rand(-1.6, 1.6), rand(0, 2), rand(-1.6, 1.6))), new THREE.Vector3(0, 1, 0), rand(1.4, 3), rand(1.4, 2.6), 0.38);
    }
    this.audio?.explosion?.();
  }

  update(dt) {
    this.time += dt;

    // tracers
    for (const t of this.tracerPool) {
      if (!t.active) continue;
      t.life -= dt;
      t.line.material.opacity = Math.max(0, t.life / t.max) * 0.95;
      if (t.life <= 0) { t.active = false; t.line.visible = false; }
    }
    // flashes
    for (let i = this.flashes.length - 1; i >= 0; i--) {
      const f = this.flashes[i]; f.life -= dt;
      const k = Math.max(0, f.life / f.max);
      if (f.sphere) {
        const s = 1 + (1 - k) * 6;
        f.sphere.scale.setScalar(s); f.sphere.material.opacity = k * 0.85;
        f.ring.scale.setScalar(1 + (1 - k) * 14); f.ring.material.opacity = k * 0.6;
        f.light.intensity = 90 * k;
      } else {
        f.sprite.material.opacity = k; f.sprite.scale.setScalar(f.sprite.scale.x * (1 + dt * 4));
        f.light.intensity = 14 * k;
      }
      if (f.life <= 0) {
        if (f.sprite) { this.scene.remove(f.sprite); f.sprite.material.dispose(); }
        if (f.sphere) { this.scene.remove(f.sphere); this.scene.remove(f.ring); f.sphere.material.dispose(); f.ring.material.dispose(); }
        this.scene.remove(f.light);
        this.flashes.splice(i, 1);
      }
    }
    // spark particles
    const sp = this.sparkGeo.attributes.position; let dirty = false;
    for (let i = 0; i < this.sparkCount; i++) {
      const d = this.sparkData[i];
      if (d.life <= 0) continue;
      d.life -= dt; dirty = true;
      if (d.life <= 0) { sp.setXYZ(i, 0, -9999, 0); continue; }
      d.vy -= 13 * dt;
      sp.setXYZ(i, sp.getX(i) + d.vx * dt, sp.getY(i) + d.vy * dt, sp.getZ(i) + d.vz * dt);
    }
    if (dirty) sp.needsUpdate = true;
    // blood
    const bp = this.bloodGeo.attributes.position; let bdirty = false;
    for (let i = 0; i < this.bloodCount; i++) {
      const d = this.bloodData[i];
      if (d.life <= 0) continue;
      d.life -= dt; bdirty = true;
      if (d.life <= 0) { bp.setXYZ(i, 0, -9999, 0); continue; }
      d.vy -= 9 * dt;
      bp.setXYZ(i, bp.getX(i) + d.vx * dt, bp.getY(i) + d.vy * dt, bp.getZ(i) + d.vz * dt);
    }
    if (bdirty) bp.needsUpdate = true;
    // shells
    for (const s of this.shells) {
      if (s.life <= 0) continue;
      s.life -= dt;
      if (s.life <= 0) { s.mesh.visible = false; continue; }
      s.vy -= 15 * dt;
      s.mesh.position.x += s.vx * dt; s.mesh.position.y += s.vy * dt; s.mesh.position.z += s.vz * dt;
      s.mesh.rotation.x += s.spin.x * dt; s.mesh.rotation.y += s.spin.y * dt; s.mesh.rotation.z += s.spin.z * dt;
      if (s.mesh.position.y < 0.02) {
        s.mesh.position.y = 0.02;
        if (!s.bounced) { s.vy = -s.vy * 0.35; s.vx *= 0.5; s.vz *= 0.5; s.bounced = true; }
        else { s.vy = 0; s.vx *= 0.75; s.vz *= 0.75; }
        s.spin.multiplyScalar(0.7);
      }
    }
    // smoke
    for (const s of this.smoke) {
      if (s.life <= 0) { if (s.sprite.visible) s.sprite.visible = false; continue; }
      s.life -= dt;
      const k = Math.max(0, s.life / s.max);
      s.sprite.material.opacity = k * s.opacity;
      s.sprite.scale.setScalar(s.scale * (1 + (1 - k) * s.grow));
      s.sprite.position.y += s.vy * dt;
      if (s.life <= 0) s.sprite.visible = false;
    }
    // decals fade
    for (const d of this.decals) {
      if (!d.active) continue;
      d.life -= dt;
      if (d.life < 3) d.mesh.material.opacity = Math.max(0, d.life / 3) * 0.55;
      if (d.life <= 0) { d.active = false; d.mesh.visible = false; }
    }
  }

  dispose() {
    for (const t of this.tracerPool) this.scene.remove(t.line);
    for (const d of this.decals) this.scene.remove(d.mesh);
    for (const s of this.shells) this.scene.remove(s.mesh);
    for (const s of this.smoke) this.scene.remove(s.sprite);
    for (const f of this.flashes) this.scene.remove(f.light);
    this.scene.remove(this.sparks); this.scene.remove(this.blood);
  }
}

const GAME_KEYS = new Set(['KeyW','KeyA','KeyS','KeyD','KeyR','KeyG','KeyC','Space','ShiftLeft','ShiftRight','Digit1','Digit2','Tab','KeyQ','KeyE']);

export class Input {
  constructor(canvas) {
    this.canvas = canvas;
    this.keys = new Set();
    this.pressed = new Set();
    this.mouse = { left: false, right: false };
    this.lookX = 0; this.lookY = 0;
    this.pointerLocked = false;
    this.enabled = false;
    this.sensitivity = 1;
    this.invert = false;
    this.touch = { moveX: 0, moveY: 0, fire: false, aim: false, active: false };
    this.isTouch = window.matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window;
    this.onLockChange = null;
    this.onKey = null;
    this._bind();
  }

  _bind() {
    window.addEventListener('keydown', (e) => {
      if (e.repeat) { if (GAME_KEYS.has(e.code)) e.preventDefault(); return; }
      if (GAME_KEYS.has(e.code) || e.code === 'Escape') {
        if (this.enabled || e.code === 'Escape') e.preventDefault();
      }
      this.keys.add(e.code);
      this.pressed.add(e.code);
      this.onKey?.(e.code);
    });
    window.addEventListener('keyup', (e) => this.keys.delete(e.code));
    window.addEventListener('blur', () => { this.keys.clear(); this.mouse.left = this.mouse.right = false; this.touch.fire = false; });
    document.addEventListener('pointerlockchange', () => {
      this.pointerLocked = document.pointerLockElement === this.canvas;
      this.onLockChange?.(this.pointerLocked);
    });
    document.addEventListener('mousemove', (e) => {
      if (!this.pointerLocked) return;
      const mx = e.movementX || 0, my = e.movementY || 0;
      this.lookX += mx * this.sensitivity;
      this.lookY += my * this.sensitivity * (this.invert ? -1 : 1);
    });
    this.canvas.addEventListener('mousedown', (e) => {
      if (e.button === 0) this.mouse.left = true;
      if (e.button === 2) this.mouse.right = true;
    });
    window.addEventListener('mouseup', (e) => {
      if (e.button === 0) this.mouse.left = false;
      if (e.button === 2) this.mouse.right = false;
    });
    this.canvas.addEventListener('contextmenu', (e) => e.preventDefault());
    this.canvas.addEventListener('wheel', (e) => e.preventDefault(), { passive: false });
    this._bindTouch();
  }

  _bindTouch() {
    const stickZone = document.getElementById('stick-zone');
    const knob = document.getElementById('stick-knob');
    const lookZone = document.getElementById('look-zone');
    if (!stickZone || !lookZone) return;
    let stickId = null, lookId = null, lx = 0, ly = 0;

    const stickRect = () => stickZone.getBoundingClientRect();
    const updateStick = (e) => {
      const r = stickRect();
      const cx = r.left + r.width / 2, cy = r.top + r.height / 2;
      let dx = e.clientX - cx, dy = e.clientY - cy;
      const max = r.width * 0.34;
      const len = Math.hypot(dx, dy);
      if (len > max) { dx = dx / len * max; dy = dy / len * max; }
      this.touch.moveX = dx / max; this.touch.moveY = dy / max;
      if (knob) knob.style.transform = `translate(${dx}px,${dy}px)`;
    };
    stickZone.addEventListener('pointerdown', (e) => {
      if (!this.enabled) return;
      e.preventDefault(); e.stopPropagation();
      stickId = e.pointerId; stickZone.setPointerCapture(e.pointerId); this.touch.active = true;
      updateStick(e);
    });
    stickZone.addEventListener('pointermove', (e) => {
      if (e.pointerId !== stickId) return;
      e.preventDefault(); updateStick(e);
    });
    const endStick = (e) => {
      if (e.pointerId !== stickId) return;
      stickId = null; this.touch.moveX = this.touch.moveY = 0;
      if (knob) knob.style.transform = 'translate(0px,0px)';
    };
    stickZone.addEventListener('pointerup', endStick);
    stickZone.addEventListener('pointercancel', endStick);

    lookZone.addEventListener('pointerdown', (e) => {
      if (!this.enabled) return;
      e.preventDefault(); lookId = e.pointerId; lx = e.clientX; ly = e.clientY;
      lookZone.setPointerCapture(e.pointerId);
    });
    lookZone.addEventListener('pointermove', (e) => {
      if (e.pointerId !== lookId) return;
      e.preventDefault();
      const dx = e.clientX - lx, dy = e.clientY - ly;
      lx = e.clientX; ly = e.clientY;
      this.lookX += dx * 1.55 * this.sensitivity;
      this.lookY += dy * 1.55 * this.sensitivity * (this.invert ? -1 : 1);
    });
    const endLook = (e) => { if (e.pointerId === lookId) lookId = null; };
    lookZone.addEventListener('pointerup', endLook);
    lookZone.addEventListener('pointercancel', endLook);

    const hold = (id, on, off) => {
      const el = document.getElementById(id); if (!el) return;
      el.addEventListener('pointerdown', (e) => { e.preventDefault(); e.stopPropagation(); el.classList.add('on'); on(); });
      const end = (e) => { e.preventDefault(); el.classList.remove('on'); off?.(); };
      el.addEventListener('pointerup', end); el.addEventListener('pointercancel', end); el.addEventListener('pointerleave', end);
    };
    hold('t-fire', () => { this.touch.fire = true; }, () => { this.touch.fire = false; });
    hold('t-aim', () => { this.touch.aim = !this.touch.aim; }, null);
    hold('t-reload', () => this.onKey?.('KeyR'), null);
    hold('t-jump', () => this.onKey?.('Space'), null);
    hold('t-switch', () => this.onKey?.('Digit2'), null);
    hold('t-nade', () => this.onKey?.('KeyG'), null);
  }

  requestLock() {
    if (this.isTouch) return;
    if (!this.pointerLocked) this.canvas.requestPointerLock?.();
  }

  exitLock() { if (document.pointerLockElement) document.exitPointerLock(); }

  consumeLook() {
    const x = this.lookX, y = this.lookY;
    this.lookX = 0; this.lookY = 0;
    return { x, y };
  }

  wasPressed(code) { return this.pressed.has(code); }
  endFrame() { this.pressed.clear(); }

  get forward() { return (this.keys.has('KeyW') ? 1 : 0) - (this.keys.has('KeyS') ? 1 : 0) - this.touch.moveY; }
  get strafe() { return (this.keys.has('KeyD') ? 1 : 0) - (this.keys.has('KeyA') ? 1 : 0) + this.touch.moveX; }
  get sprint() { return this.keys.has('ShiftLeft') || this.keys.has('ShiftRight'); }
  get jump() { return this.keys.has('Space'); }
  get crouch() { return this.keys.has('KeyC'); }
  get fire() { return this.mouse.left || this.touch.fire; }
  get aim() { return this.mouse.right || this.touch.aim; }
}

import * as THREE from 'three';

const clamp = (x, a, b) => Math.max(a, Math.min(b, x));
const lerp = (a, b, t) => a + (b - a) * t;

export class Player {
  constructor(camera, input, world, audio, hud) {
    this.camera = camera;
    this.input = input;
    this.world = world;
    this.audio = audio;
    this.hud = hud;
    this.position = new THREE.Vector3(0, 0, 19);
    this.velocity = new THREE.Vector3();
    this.yaw = 0; this.pitch = 0;
    this.eye = 1.68; this.crouchEye = 1.08; this.eyeCurrent = 1.68;
    this.radius = 0.38;
    this.maxHealth = 100; this.health = 100;
    this.dead = false;
    this.onGround = true;
    this.ads = false;
    this.sprinting = false;
    this.moving = false;
    this.speed = 0;
    this.regenTimer = 0;
    this.damageFlash = 0;
    this.trauma = 0;
    this.recoilPitch = 0; this.recoilYaw = 0;
    this.recoilVelP = 0; this.recoilVelY = 0;
    this.bobPhase = 0; this.bobAmp = 0;
    this.stepDist = 0;
    this.fovTarget = 78;
    this.godMode = false;
    this.invuln = 0;
    this.time = 0;
    this.landKick = 0;
    this.deathTime = 0;
    this.lastDamageDir = 0;
    this.damageDirTime = 0;
    this.hitDirection = new THREE.Vector3();
    this._tmpDir = new THREE.Vector3();
    this._shake = { x: 0, y: 0, z: 0, rx: 0, ry: 0, rz: 0 };
    this._wasGrounded = true;
    camera.rotation.order = 'YXZ';
  }

  reset() {
    this.position.set(0, 0, 19);
    this.velocity.set(0, 0, 0);
    this.yaw = 0; this.pitch = 0;
    this.health = this.maxHealth;
    this.dead = false;
    this.eyeCurrent = this.eye;
    this.regenTimer = 0;
    this.trauma = 0; this.recoilPitch = 0; this.recoilYaw = 0;
    this.damageFlash = 0;
    this.time = 0;
    this.landKick = 0;
    this.updateCamera(0);
  }

  addShake(amount) { this.trauma = Math.min(1, this.trauma + amount); }
  addRecoil(pitch, yaw) {
    this.recoilVelP -= pitch;
    this.recoilVelY += yaw;
    this.recoilPitch += pitch * 0.55;
    this.recoilYaw += yaw * 0.55;
  }

  takeDamage(amount, sourcePos = null) {
    if (this.dead || this.godMode || this.invuln > 0) return;
    this.health = Math.max(0, this.health - amount);
    this.regenTimer = 0;
    this.damageFlash = Math.min(1, this.damageFlash + 0.35 + amount / 60);
    this.addShake(Math.min(0.55, 0.16 + amount / 90));
    this.audio?.hurt?.();
    if (sourcePos) {
      const dir = Math.atan2(sourcePos.x - this.position.x, sourcePos.z - this.position.z);
      this.lastDamageDir = dir - this.yaw;
      this.damageDirTime = 1.2;
    }
    this.hud?.damage(amount);
    this.hud?.setHealth(this.health);
    if (this.health <= 0) {
      this.dead = true;
      this.deathTime = 0;
      this.input.exitLock();
      this.audio?.defeat?.();
      this.hud?.lowHealth(false);
    } else if (this.health < 30) this.hud?.lowHealth(true);
  }

  heal(amount) {
    if (this.dead) return;
    this.health = Math.min(this.maxHealth, this.health + amount);
    this.hud?.setHealth(this.health);
    if (this.health >= 30) this.hud?.lowHealth(false);
  }

  update(dt) {
    if (this.dead) { this.deathTime += dt; this.updateDeathCamera(dt); return; }
    this.time += dt;
    if (this.invuln > 0) this.invuln -= dt;

    const look = this.input.consumeLook();
    this.yaw -= look.x * 0.00215;
    this.pitch -= look.y * 0.00215;
    this.pitch = clamp(this.pitch, -1.46, 1.38);

    // movement input
    let fwd = clamp(this.input.forward, -1, 1);
    let strafe = clamp(this.input.strafe, -1, 1);
    const len = Math.hypot(fwd, strafe);
    if (len > 1) { fwd /= len; strafe /= len; }
    const wantsSprint = this.input.sprint && fwd > 0.25 && !this.ads && !this.input.crouch;
    this.sprinting = wantsSprint && !this.dead;
    const crouching = this.input.crouch && this.onGround;
    this.eyeCurrent = lerp(this.eyeCurrent, crouching ? this.crouchEye : this.eye, clamp(dt * 10, 0, 1));

    let maxSpeed = 5.1;
    if (crouching) maxSpeed = 2.5;
    else if (this.ads) maxSpeed = 3.0;
    else if (this.sprinting) maxSpeed = 7.4;

    const sin = Math.sin(this.yaw), cos = Math.cos(this.yaw);
    const wishX = (-sin * fwd + cos * strafe);
    const wishZ = (-cos * fwd - sin * strafe);
    const accel = this.onGround ? (len > 0 ? 34 : 22) : 6;
    const targetVX = wishX * maxSpeed, targetVZ = wishZ * maxSpeed;
    this.velocity.x = lerp(this.velocity.x, targetVX, clamp(accel * dt, 0, 1));
    this.velocity.z = lerp(this.velocity.z, targetVZ, clamp(accel * dt, 0, 1));

    // jump
    if (this.input.jump && this.onGround) {
      this.velocity.y = 5.0; this.onGround = false;
      this.audio?.step?.(false);
    }
    if (!this.onGround) this.velocity.y -= 16.5 * dt;

    // integrate + collide
    const beforeY = this.position.y;
    this.position.x += this.velocity.x * dt;
    this.position.z += this.velocity.z * dt;
    this.position.y += this.velocity.y * dt;
    if (this.position.y <= 0) {
      if (!this._wasGrounded && this.velocity.y < -3) { this.addShake(0.12); this.landKick = 0.06; this.audio?.step?.(false); }
      this.position.y = 0; this.velocity.y = 0; this.onGround = true;
    } else this.onGround = false;
    this._wasGrounded = this.onGround;
    this.world.collide(this.position, this.radius, this.eye);

    const horiz = Math.hypot(this.velocity.x, this.velocity.z);
    this.speed = horiz;
    this.moving = horiz > 0.4;
    if (this.moving && this.onGround) {
      this.bobPhase += dt * (5.2 + horiz * 0.85);
      this.bobAmp = lerp(this.bobAmp, this.ads ? 0.006 : this.sprinting ? 0.05 : 0.028, dt * 6);
      this.stepDist += horiz * dt;
      const stepGap = this.sprinting ? 2.1 : 2.5;
      if (this.stepDist > stepGap) { this.stepDist = 0; this.audio?.step?.(false); }
    } else {
      this.bobAmp = lerp(this.bobAmp, 0, dt * 5);
    }

    // regen
    this.regenTimer += dt;
    if (this.regenTimer > 5.2 && this.health < this.maxHealth) {
      this.health = Math.min(this.maxHealth, this.health + 17 * dt);
      this.hud?.setHealth(this.health);
      if (this.health >= 30) this.hud?.lowHealth(false);
    }

    // recoil spring
    this.recoilVelP += (-this.recoilPitch * 190 - this.recoilVelP * 24) * dt;
    this.recoilPitch += this.recoilVelP * dt;
    this.recoilVelY += (-this.recoilYaw * 190 - this.recoilVelY * 24) * dt;
    this.recoilYaw += this.recoilVelY * dt;

    // damage flash & directional
    this.damageFlash = Math.max(0, this.damageFlash - dt * 1.6);
    if (this.damageDirTime > 0) this.damageDirTime -= dt;

    // trauma
    this.trauma = Math.max(0, this.trauma - dt * 1.9);
    const t2 = this.trauma * this.trauma;
    const s = this._shake;
    s.x = (Math.random() - 0.5) * 0.045 * t2;
    s.y = (Math.random() - 0.5) * 0.045 * t2;
    s.z = (Math.random() - 0.5) * 0.03 * t2;
    s.rx = (Math.random() - 0.5) * 0.003 * t2;
    s.ry = (Math.random() - 0.5) * 0.003 * t2;
    s.rz = (Math.random() - 0.5) * 0.006 * t2;
    this.landKick *= Math.exp(-dt * 9);

    // fov
    const sprintFov = this.sprinting ? 5 : 0;
    const target = this.fovTarget + sprintFov;
    if (Math.abs(this.camera.fov - target) > 0.02) {
      this.camera.fov = lerp(this.camera.fov, target, clamp(dt * 10, 0, 1));
      this.camera.updateProjectionMatrix();
    }
    this.updateCamera(dt);
  }

  updateCamera(dt) {
    const bob = this.bobAmp;
    const by = Math.sin(this.bobPhase * 2) * bob;
    const bx = Math.cos(this.bobPhase) * bob * 0.7;
    const roll = Math.cos(this.bobPhase) * bob * 0.7;
    this.camera.position.set(
      this.position.x + bx + this._shake.x,
      this.position.y + this.eyeCurrent + by + this._shake.y - this.landKick,
      this.position.z + this._shake.z
    );
    this.camera.rotation.y = this.yaw + this._shake.ry;
    this.camera.rotation.x = this.pitch - this.recoilPitch + this._shake.rx;
    this.camera.rotation.z = roll + this._shake.rz;
  }

  updateDeathCamera(dt) {
    // fall to the ground and tilt the view
    const k = clamp(this.deathTime * 1.6, 0, 1);
    const e = 1 - Math.pow(1 - k, 2);
    this.camera.position.y = lerp(this.position.y + this.eyeCurrent, this.position.y + 0.32, e);
    this.camera.rotation.z = lerp(0, 1.2, e);
    this.camera.rotation.x = lerp(this.pitch - this.recoilPitch, 0.5, e);
  }
}

import * as THREE from 'three';

const clamp = (x, a, b) => Math.max(a, Math.min(b, x));
const lerp = (a, b, t) => a + (b - a) * t;
const rand = (a, b) => a + Math.random() * (b - a);

const DEFS = {
