    id: 'rifle', name: 'VECTOR-7', mode: 'AUTO / 5.56', magSize: 30, reserveMax: 300,
    damage: 33, headMul: 2.9, rpm: 760, auto: true, reloadTime: 2.05, switchTime: 0.42,
    adsFov: 51, hipSpread: 0.026, adsSpread: 0.0045, moveSpread: 0.012,
    recoil: 0.0095, recoilYaw: 0.0032, adsRecoilMul: 0.55, muzzle: [0, 0.02, -0.96],
    hip: new THREE.Vector3(0.195, -0.185, -0.36), ads: new THREE.Vector3(0, -0.1005, -0.265),
    hipRot: new THREE.Euler(0.015, 0.075, -0.025), adsRot: new THREE.Euler(0, 0, 0),
  },
  pistol: {
    id: 'pistol', name: 'P9 SIDEARM', mode: 'SEMI / 9MM', magSize: 12, reserveMax: Infinity,
    damage: 49, headMul: 2.6, rpm: 430, auto: false, reloadTime: 1.55, switchTime: 0.35,
    adsFov: 60, hipSpread: 0.023, adsSpread: 0.006, moveSpread: 0.011,
    recoil: 0.012, recoilYaw: 0.0042, adsRecoilMul: 0.6, muzzle: [0, 0.032, -0.34],
    hip: new THREE.Vector3(0.22, -0.20, -0.40), ads: new THREE.Vector3(0, -0.078, -0.30),
    hipRot: new THREE.Euler(0.02, 0.09, -0.02), adsRot: new THREE.Euler(0, 0, 0),
  },
};

function mat(color, metalness, roughness, extra = {}) {
  return new THREE.MeshStandardMaterial({ color, metalness, roughness, envMapIntensity: 1.2, ...extra });
}

function box(w, h, d, x, y, z, m, rot = null) {
  const b = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), m);
  b.position.set(x, y, z);
  if (rot) b.rotation.set(rot.x || 0, rot.y || 0, rot.z || 0);
  return b;
}
function cyl(r1, r2, h, x, y, z, m, seg = 12) {
  const c = new THREE.Mesh(new THREE.CylinderGeometry(r1, r2, h, seg), m);
  c.rotation.x = Math.PI / 2; c.position.set(x, y, z);
  return c;
}

export class WeaponSystem {
  constructor(camera, scene, input, player, world, enemies, fx, audio, hud) {
    this.camera = camera; this.scene = scene; this.input = input; this.player = player;
    this.world = world; this.enemies = enemies; this.fx = fx; this.audio = audio; this.hud = hud;
    this.defs = DEFS;
    this.current = 'rifle';
    this.ammo = { rifle: { mag: 30, reserve: 180 }, pistol: { mag: 12, reserve: Infinity } };
    this.grenades = 3; this.maxGrenades = 3;
    this.grenadeCooldown = 0;
    this.projectiles = [];
    this.fireTimer = 0; this.triggerHeld = false;
    this.reloading = false; this.reloadT = 0; this.reloadStage = 0;
    this.switching = false; this.switchT = 0; this.switchTarget = null; this.switchStage = 0;
    this.aimT = 0;
    this.recoilVisual = 0; this.recoilVisualVel = 0;
    this.kickZ = 0;
    this.swayX = 0; this.swayY = 0;
    this.prevYaw = 0; this.prevPitch = 0;
    this.bobTime = 0;
    this.muzzleFlashT = 0;
    this.shotsFired = 0; this.shotsHit = 0; this.headshots = 0;
    this.shellTimer = 0;
    this.enabled = false;
    this.holder = new THREE.Group(); this.camera.add(this.holder);
    this.rifle = this.buildRifle();
    this.pistol = this.buildPistol();
    this.holder.add(this.rifle, this.pistol);
    this.pistol.visible = false;
    this.currentMuzzle = new THREE.Object3D();
    this.rifle.add(this.currentMuzzle); this.currentMuzzle.position.set(...DEFS.rifle.muzzle);
    this.pistolMuzzle = new THREE.Object3D();
    this.pistol.add(this.pistolMuzzle); this.pistolMuzzle.position.set(...DEFS.pistol.muzzle);
    this.flashlight = new THREE.SpotLight(0xe8f0ff, 20, 26, 0.42, 0.72, 1.5);
    this.flashlight.position.set(0.06, 0.03, -0.55);
    this.flashlight.target = new THREE.Object3D(); this.flashlight.target.position.set(0.06, 0, -18);
    this.holder.add(this.flashlight); this.holder.add(this.flashlight.target);
    this.flashlight.visible = false;
    this.holder.visible = false;
    this.reset();
  }

  buildRifle() {
    const g = new THREE.Group();
    const gun = mat(0x23272b, 0.9, 0.36);
    const gunDark = mat(0x141719, 0.85, 0.44);
    const polymer = mat(0x1c1e1f, 0.25, 0.68);
    const tan = mat(0x76674e, 0.35, 0.62);
    const accent = mat(0x3d474d, 0.8, 0.4);
    const rubber = mat(0x0e0f10, 0.05, 0.9);
    const red = new THREE.MeshBasicMaterial({ color: 0xff2a1c });
    const lensMat = new THREE.MeshBasicMaterial({ color: 0x9fe6ff, transparent: true, opacity: 0.16, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide });

    // receiver
    g.add(box(0.074, 0.088, 0.36, 0, 0, -0.18, gun));
    g.add(box(0.078, 0.024, 0.34, 0, 0.056, -0.18, gunDark));
    // top rail
    for (let i = 0; i < 12; i++) g.add(box(0.05, 0.008, 0.014, 0, 0.072, -0.34 + i * 0.032, gunDark));
    // handguard
    g.add(box(0.064, 0.072, 0.40, 0, 0.002, -0.56, tan));
    for (let i = 0; i < 7; i++) {
      const s = box(0.066, 0.012, 0.028, 0, -0.006, -0.42 - i * 0.048, gunDark);
      g.add(s);
    }
    g.add(box(0.068, 0.014, 0.38, 0, 0.05, -0.56, tan));
    for (let i = 0; i < 9; i++) g.add(box(0.045, 0.006, 0.012, 0, 0.06, -0.4 - i * 0.04, gunDark));
    // barrel & muzzle
    g.add(cyl(0.014, 0.014, 0.32, 0, 0.012, -0.89, gunDark));
    g.add(cyl(0.023, 0.02, 0.09, 0, 0.012, -1.02, gun));
    g.add(box(0.03, 0.05, 0.06, 0, 0.012, -1.04, gunDark));
    // gas block
    g.add(box(0.036, 0.045, 0.06, 0, 0.035, -0.78, gunDark));
    // stock
    g.add(box(0.05, 0.075, 0.20, 0, -0.005, 0.10, polymer));
    g.add(box(0.056, 0.11, 0.035, 0, -0.012, 0.208, rubber));
    g.add(box(0.045, 0.03, 0.12, 0, 0.028, 0.08, gunDark));
    // pistol grip
    g.add(box(0.052, 0.115, 0.062, 0, -0.092, -0.02, polymer, { x: 0.28 }));
    g.add(box(0.054, 0.018, 0.07, 0, -0.148, -0.035, rubber, { x: 0.28 }));
    // trigger guard
    const guard = new THREE.Mesh(new THREE.TorusGeometry(0.032, 0.005, 5, 12, Math.PI), gunDark);
    guard.rotation.z = Math.PI; guard.position.set(0, -0.062, -0.055); g.add(guard);
    g.add(box(0.008, 0.03, 0.03, 0, -0.055, -0.09, gunDark));
    // magazine
    this.rifleMag = new THREE.Group();
    const magBody = box(0.052, 0.15, 0.085, 0, -0.115, -0.16, gunDark, { x: -0.12 });
    const magBody2 = box(0.05, 0.07, 0.08, 0, -0.205, -0.148, gunDark, { x: -0.24 });
    this.rifleMag.add(magBody, magBody2);
    g.add(this.rifleMag);
    // vertical foregrip
    g.add(box(0.034, 0.10, 0.04, 0, -0.078, -0.52, polymer));
    g.add(box(0.036, 0.012, 0.044, 0, -0.128, -0.52, rubber));
    // flashlight
    g.add(cyl(0.018, 0.018, 0.10, 0.048, 0.005, -0.67, gunDark));
    const lens = new THREE.Mesh(new THREE.CircleGeometry(0.017, 12), new THREE.MeshBasicMaterial({ color: 0xdceeff, emissive: 0x88bbff }));
    lens.position.set(0.048, 0.005, -0.721); g.add(lens);
    // holo sight
    const sight = new THREE.Group(); sight.position.set(0, 0.098, -0.145);
    sight.add(box(0.05, 0.018, 0.075, 0, -0.024, 0, gunDark));
    sight.add(box(0.008, 0.062, 0.06, -0.026, 0.004, 0, gunDark));
    sight.add(box(0.008, 0.062, 0.06, 0.026, 0.004, 0, gunDark));
    sight.add(box(0.052, 0.008, 0.06, 0, 0.037, 0, gunDark));
    const glass = new THREE.Mesh(new THREE.PlaneGeometry(0.044, 0.048), lensMat);
    glass.position.set(0, 0.005, -0.003); sight.add(glass);
    const dot = new THREE.Mesh(new THREE.CircleGeometry(0.0032, 12), red);
    dot.position.set(0, 0.005, -0.006); sight.add(dot);
    const dotGlow = new THREE.Sprite(new THREE.SpriteMaterial({ map: this._dotTex(), color: 0xff4433, transparent: true, opacity: 0.8, blending: THREE.AdditiveBlending, depthWrite: false }));
    dotGlow.scale.set(0.022, 0.022, 1); dotGlow.position.set(0, 0.005, -0.01); sight.add(dotGlow);
    g.add(sight);
    // laser unit
    g.add(box(0.032, 0.03, 0.05, -0.045, 0.012, -0.63, gunDark));
    // hands
    const glove = mat(0x2a2620, 0.1, 0.82);
    const sleeve = mat(0x3a3c36, 0.05, 0.92);
    const rightHand = box(0.065, 0.06, 0.09, 0.005, -0.085, -0.02, glove, { x: 0.3 });
    g.add(rightHand);
    g.add(box(0.08, 0.09, 0.17, 0.03, -0.13, 0.09, sleeve, { x: 0.2, y: 0.2 }));
    const leftHand = box(0.07, 0.065, 0.10, 0.005, -0.078, -0.50, glove, { x: 0.1, z: -0.15 });
    g.add(leftHand);
    g.add(box(0.085, 0.085, 0.22, -0.045, -0.11, -0.38, sleeve, { x: -0.3, y: -0.35, z: 0.2 }));
    // charging handle
    g.add(box(0.03, 0.02, 0.05, 0.035, 0.04, 0.015, gunDark));
    return g;
  }

  buildPistol() {
    const g = new THREE.Group();
    const gun = mat(0x2c3033, 0.9, 0.34);
    const dark = mat(0x131517, 0.8, 0.46);
    const polymer = mat(0x1b1d1e, 0.15, 0.78);
    const glove = mat(0x2a2620, 0.1, 0.82);
    const sleeve = mat(0x3a3c36, 0.05, 0.92);
    g.add(box(0.052, 0.055, 0.21, 0, 0.02, -0.14, gun));
    g.add(box(0.049, 0.036, 0.19, 0, -0.018, -0.125, polymer));
    g.add(cyl(0.014, 0.014, 0.06, 0, 0.02, -0.26, dark));
    g.add(box(0.012, 0.015, 0.18, 0, 0.053, -0.145, dark));
    // grip
    g.add(box(0.05, 0.12, 0.07, 0, -0.088, -0.005, polymer, { x: 0.26 }));
    g.add(box(0.052, 0.02, 0.075, 0, -0.15, -0.018, dark, { x: 0.26 }));
    // trigger guard
    const guard = new THREE.Mesh(new THREE.TorusGeometry(0.026, 0.004, 5, 12, Math.PI), dark);
    guard.rotation.z = Math.PI; guard.position.set(0, -0.052, -0.065); g.add(guard);
    // sights with tritium dots
    g.add(box(0.02, 0.018, 0.02, 0, 0.06, -0.235, dark));
    g.add(box(0.036, 0.016, 0.02, 0, 0.06, -0.045, dark));
    const dotMat = new THREE.MeshBasicMaterial({ color: 0x7dff9a });
    for (const x of [-0.011, 0.011]) {
      const d = new THREE.Mesh(new THREE.CircleGeometry(0.0024, 8), dotMat);
      d.position.set(x, 0.06, -0.242); g.add(d);
    }
    g.add(box(0.055, 0.005, 0.04, 0, 0.047, -0.16, gun));
    // hands
    g.add(box(0.062, 0.075, 0.075, 0.0, -0.085, 0.0, glove));
    g.add(box(0.075, 0.08, 0.16, 0.035, -0.115, 0.085, sleeve, { x: 0.15, y: 0.28 }));
    const support = box(0.06, 0.07, 0.08, -0.03, -0.085, -0.005, glove, { z: 0.3 });
    g.add(support);
    g.add(box(0.075, 0.085, 0.17, -0.075, -0.115, 0.08, sleeve, { x: 0.12, y: -0.2 }));
    return g;
  }

  _dotTex() {
    if (this._dotTexture) return this._dotTexture;
    const c = document.createElement('canvas'); c.width = c.height = 64;
    const x = c.getContext('2d');
    const g = x.createRadialGradient(32, 32, 0, 32, 32, 32);
    g.addColorStop(0, 'rgba(255,255,255,1)'); g.addColorStop(0.2, 'rgba(255,90,60,.9)'); g.addColorStop(0.55, 'rgba(255,30,20,.25)'); g.addColorStop(1, 'rgba(255,0,0,0)');
    x.fillStyle = g; x.fillRect(0, 0, 64, 64);
    this._dotTexture = new THREE.CanvasTexture(c); this._dotTexture.colorSpace = THREE.SRGBColorSpace;
    return this._dotTexture;
  }

  reset() {
    this.current = 'rifle';
    this.ammo = { rifle: { mag: 30, reserve: 180 }, pistol: { mag: 12, reserve: Infinity } };
    this.grenades = 3;
    this.reloading = false; this.reloadT = 0; this.reloadStage = 0;
    this.switching = false; this.fireTimer = 0;
    this.aimT = 0; this.recoilVisual = 0; this.recoilVisualVel = 0; this.kickZ = 0;
    this.swayX = 0; this.swayY = 0;
    this.shotsFired = 0; this.shotsHit = 0; this.headshots = 0;
    this.rifle.visible = true; this.pistol.visible = false;
    this.currentMuzzle = this.rifle.children.find(c => c.position.z < -0.9) || this.currentMuzzle;
    this.projectiles.forEach(p => this.scene.remove(p.mesh)); this.projectiles = [];
    this.hud?.setGrenades(this.grenades);
    this.hud?.setWeapon(this.defs.rifle.name, this.defs.rifle.mode);
    this.hud?.setAmmo(this.ammo.rifle.mag, this.ammo.rifle.reserve);
    this.holder.visible = false;
    this.flashlight.visible = false;
    this.player.fovTarget = 78;
  }

  setEnabled(on) {
    this.enabled = on;
    this.holder.visible = on;
    this.flashlight.visible = on;
    this.player.fovTarget = on ? 78 : this.player.fovTarget;
    if (!on) { this.pistol.visible = false; this.rifle.visible = true; }
  }

  get def() { return this.defs[this.current]; }
  get ammoNow() { return this.ammo[this.current]; }

  addReserve(amount) {
    for (const k of ['rifle', 'pistol']) {
      if (this.ammo[k].reserve === Infinity) continue;
      this.ammo[k].reserve = Math.min(this.defs[k].reserveMax, this.ammo[k].reserve + amount);
    }
    this.hud?.setAmmo(this.ammoNow.mag, this.ammoNow.reserve);
  }

  addGrenades(n) { this.grenades = Math.min(this.maxGrenades, this.grenades + n); this.hud?.setGrenades(this.grenades); }

  key(code) {
    if (!this.enabled) return;
    if (code === 'KeyR') this.reload();
    if (code === 'Digit1') this.switchTo('rifle');
    if (code === 'Digit2') this.switchTo('pistol');
    if (code === 'KeyG') this.throwGrenade();
    if (code === 'KeyQ') this.switchTo(this.current === 'rifle' ? 'pistol' : 'rifle');
  }

  reload() {
    if (this.reloading || this.switching) return;
    if (this.ammoNow.mag >= this.def.magSize) return;
    if (this.ammoNow.reserve !== Infinity && this.ammoNow.reserve <= 0) return;
    this.reloading = true; this.reloadT = 0; this.reloadStage = 0;
    this.hud?.setReloading(true);
    this.audio?.reload?.(0);
  }

  switchTo(id) {
    if (id === this.current || this.switching) return;
    this.switching = true; this.switchT = 0; this.switchTarget = id; this.switchStage = 0;
    this.reloading = false; this.hud?.setReloading(false);
    this.audio?.switchWeapon?.();
  }

  switchImmediate(id) {
    this.current = id;
    this.rifle.visible = id === 'rifle'; this.pistol.visible = id === 'pistol';
    this.currentMuzzle = id === 'rifle' ? this.rifle.children.find(c => c.position.z < -0.9) : this.pistolMuzzle;
    const d = this.def;
    this.hud?.setWeapon(d.name, d.mode);
    this.hud?.setAmmo(this.ammoNow.mag, this.ammoNow.reserve);
    this.hud?.setSlot(id);
    this.player.fovTarget = 78;
  }

  finishReload() {
    const a = this.ammoNow;
    const need = this.def.magSize - a.mag;
    if (a.reserve === Infinity) a.mag = this.def.magSize;
    else { const take = Math.min(need, a.reserve); a.mag += take; a.reserve -= take; }
    this.reloading = false;
    this.hud?.setReloading(false);
    this.hud?.setAmmo(a.mag, a.reserve);
  }

  throwGrenade() {
    if (!this.enabled || this.grenadeCooldown > 0 || this.grenades <= 0) return;
    this.grenades--; this.hud?.setGrenades(this.grenades); this.grenadeCooldown = 1.1;
    this.audio?.throwGrenade?.();
    const dir = new THREE.Vector3(); this.camera.getWorldDirection(dir);
    const pos = this.camera.position.clone().addScaledVector(dir, 0.45).add(new THREE.Vector3(0, -0.12, 0));
    const mesh = new THREE.Mesh(new THREE.SphereGeometry(0.055, 10, 8), new THREE.MeshStandardMaterial({ color: 0x39412c, roughness: 0.6, metalness: 0.4 }));
    const band = new THREE.Mesh(new THREE.TorusGeometry(0.056, 0.008, 4, 12), new THREE.MeshStandardMaterial({ color: 0x8f2f1a }));
    band.rotation.x = Math.PI / 2; mesh.add(band);
    mesh.position.copy(pos); this.scene.add(mesh);
    const vel = dir.clone().multiplyScalar(15).add(new THREE.Vector3(0, 4.2, 0));
    this.projectiles.push({ mesh, vel, life: 2.7, trail: 0, exploded: false });
    this.player.addShake(0.04);
    this.hud?.hint('FRAG OUT');
  }

  explodeGrenade(p) {
    this.fx.explosion(p, 8);
    this.player.addShake(0.85);
    const pd = this.player.position.clone().setY(1).distanceTo(p);
    if (pd < 8) this.player.takeDamage(Math.round(70 * (1 - pd / 8)), p);
    this.enemies?.damageRadius?.(p, 8, 130);
  }

  fire() {
    if (!this.enabled || this.reloading || this.switching || this.fireTimer > 0) return;
    const a = this.ammoNow;
    if (a.mag <= 0) { this.audio?.dryFire?.(); this.fireTimer = 0.18; this.reload(); return; }
    const def = this.def;
    a.mag--; this.shotsFired++;
    this.fireTimer = 60 / def.rpm;
    if (def.auto) this.triggerHeld = true;
    this.hud?.setAmmo(a.mag, a.reserve);

    const aim = this.aimT;
    const moveFactor = clamp(this.player.speed / 7, 0, 1);
    const spread = lerp(def.hipSpread, def.adsSpread, aim) + moveFactor * def.moveSpread * (1 - aim * 0.7);
    const dir = new THREE.Vector3(); this.camera.getWorldDirection(dir);
    const right = new THREE.Vector3(1, 0, 0).applyQuaternion(this.camera.quaternion);
    const up = new THREE.Vector3(0, 1, 0).applyQuaternion(this.camera.quaternion);
    const ang = Math.random() * Math.PI * 2, rad = Math.sqrt(Math.random()) * spread;
    dir.addScaledVector(right, Math.cos(ang) * rad).addScaledVector(up, Math.sin(ang) * rad).normalize();

    // muzzle position in world
    const muzzleObj = this.current === 'rifle' ? this.rifle : this.pistol;
    const muzzleLocal = this.current === 'rifle' ? new THREE.Vector3(...def.muzzle) : new THREE.Vector3(...def.muzzle);
    const muzzle = muzzleObj.localToWorld(muzzleLocal.clone());
    if (this.current === 'rifle' && this.rifleMag && !this.rifleMag.visible) this.rifleMag.visible = true;

    const maxDist = 180;
    const envHit = this.world.raycast(this.camera.position, dir, maxDist);
    const enemyHit = this.enemies?.raycast(this.camera.position, dir, envHit ? envHit.distance : maxDist);
    let end;
    if (enemyHit) {
      end = enemyHit.point;
      const falloff = clamp(1 - Math.max(0, enemyHit.distance - 28) / 90, 0.7, 1);
      const isHead = enemyHit.head;
      const dmg = def.damage * falloff * (isHead ? def.headMul : 1);
      const killed = this.enemies.damage(enemyHit.enemy, dmg, isHead, enemyHit.point, dir);
      this.shotsHit++;
      if (isHead) this.headshots++;
      this.fx.spawnBlood(enemyHit.point, dir, isHead ? 12 : 7);
      this.hud?.hitmarker(isHead, killed);
      this.audio?.hit?.(isHead);
    } else if (envHit) {
      end = envHit.point;
      const mat = this.surfaceOf(envHit.collider);
      const n = this.normalFor(envHit);
      this.fx.impact(end, n, mat);
    } else {
      end = this.camera.position.clone().addScaledVector(dir, maxDist);
    }
    this.fx.tracer(muzzle, end, this.current === 'rifle' ? 0xffd9a0 : 0xffe6c2);
    this.fx.muzzleFlash(muzzle, dir, this.current === 'rifle' ? 1 : 0.75);
    this.audio.shot(this.current);
    this.player.addShake(this.aimT > 0.5 ? 0.045 : 0.095);
    const recoilMul = this.aimT > 0.5 ? def.adsRecoilMul : 1;
    this.player.addRecoil(def.recoil * recoilMul * (this.current === 'rifle' ? rand(0.85, 1.15) : 1), def.recoilYaw * rand(-1, 1) * (this.aimT > 0.5 ? 0.5 : 1));
    this.recoilVisualVel += def.recoil * 11 * recoilMul;
    this.kickZ += 0.028 * recoilMul;

    // eject shell
    this.shellTimer = 0.01;
    if (a.mag === 0) this.audio?.dryFire?.();
  }

  surfaceOf(collider) {
    const name = collider?.mesh?.name || '';
    if (name.includes('crate')) return 'wood';
    if (name) return 'concrete';
    return Math.random() > 0.5 ? 'metal' : 'concrete';
  }

  normalFor(hit) {
    if (hit.collider === 'ground') return new THREE.Vector3(0, 1, 0);
    const c = hit.collider, p = hit.point;
    const eps = 0.03;
    if (Math.abs(p.x - c.x1) < eps) return new THREE.Vector3(-1, 0, 0);
    if (Math.abs(p.x - c.x2) < eps) return new THREE.Vector3(1, 0, 0);
    if (Math.abs(p.z - c.z1) < eps) return new THREE.Vector3(0, 0, -1);
    if (Math.abs(p.z - c.z2) < eps) return new THREE.Vector3(0, 0, 1);
    return new THREE.Vector3(0, 1, 0);
  }

  update(dt) {
    if (!this.enabled) { this.holder.visible = false; this.flashlight.visible = false; return; }
    this.holder.visible = true; this.flashlight.visible = true;
    const input = this.input;
    this.fireTimer = Math.max(0, this.fireTimer - dt);
    this.grenadeCooldown = Math.max(0, this.grenadeCooldown - dt);

    // aim
    const canAim = !this.reloading && !this.switching && !this.player.sprinting;
    const wantAim = input.aim && canAim;
    this.aimT = lerp(this.aimT, wantAim ? 1 : 0, clamp(dt * 13, 0, 1));
    this.player.ads = this.aimT > 0.5;
    this.player.fovTarget = lerp(78, this.def.adsFov, this.aimT);
    this.hud?.setAim(this.aimT);

    // fire
    if (input.fire) {
      if (!this.triggerHeld || this.def.auto) this.fire();
      this.triggerHeld = true;
    } else this.triggerHeld = false;

    // reload progress
    if (this.reloading) {
      this.reloadT += dt;
      const k = this.reloadT / this.def.reloadTime;
      if (k >= 0.28 && this.reloadStage === 0) {
        this.reloadStage = 1; this.audio?.reload?.(1);
        if (this.rifleMag) this.rifleMag.position.y -= 0.18;
      }
      if (k >= 0.58 && this.reloadStage === 1) {
        this.reloadStage = 2; this.audio?.reload?.(2);
        if (this.rifleMag) this.rifleMag.position.y = 0;
      }
      if (k >= 0.86 && this.reloadStage === 2) {
        this.reloadStage = 3; this.audio?.reload?.(0);
      }
      if (k >= 1) this.finishReload();
    }

    // switching
    if (this.switching) {
      this.switchT += dt;
      const k = this.switchT / this.def.switchTime;
      if (k >= 0.5 && this.switchStage === 0) { this.switchStage = 1; this.switchImmediate(this.switchTarget); }
      if (k >= 1) { this.switching = false; }
    }

    // shells
    if (this.shellTimer > 0) {
      this.shellTimer -= dt;
      if (this.shellTimer <= 0) {
        const right = new THREE.Vector3(1, 0, 0).applyQuaternion(this.camera.quaternion);
        const up = new THREE.Vector3(0, 1, 0).applyQuaternion(this.camera.quaternion);
        const pos = this.camera.position.clone().addScaledVector(right, 0.22).addScaledVector(up, -0.05).addScaledVector(this.getForward(), 0.35);
        const dir = right.clone().addScaledVector(up, 0.25);
        this.fx.shell(pos, dir);
      }
    }

    // projectile grenades
    for (let i = this.projectiles.length - 1; i >= 0; i--) {
      const p = this.projectiles[i];
      p.life -= dt; p.trail -= dt;
      p.vel.y -= 15 * dt;
      const next = p.mesh.position.clone().addScaledVector(p.vel, dt);
      let explode = false;
      if (next.y <= 0.09) {
        next.y = 0.09;
        if (p.vel.y < -0.5) { p.vel.y = -p.vel.y * 0.36; p.vel.x *= 0.62; p.vel.z *= 0.62; this.audio?.grenadeBounce?.(); }
        else { p.vel.y = 0; p.vel.x *= 0.9; p.vel.z *= 0.9; }
      }
      // collide with walls
      const fromC = p.mesh.position.clone();
      const dir = next.clone().sub(fromC);
      const dist = dir.length();
      if (dist > 0.0001) {
        dir.divideScalar(dist);
        const hit = this.world.raycast(fromC, dir, dist + 0.05);
        if (hit && hit.collider !== 'ground') {
          const n = this.normalFor(hit);
          p.vel.reflect(n).multiplyScalar(0.42);
          next.copy(fromC).addScaledVector(n, 0.03);
          this.audio?.grenadeBounce?.();
        }
      }
      p.mesh.position.copy(next);
      p.mesh.rotation.x += dt * 10; p.mesh.rotation.z += dt * 6;
      if (p.trail <= 0) {
        p.trail = 0.05;
        this.fx.spawnSmoke(p.mesh.position.clone(), new THREE.Vector3(0, 1, 0), 0.18, 0.5, 0.15);
      }
      if (p.life <= 0) explode = true;
      if (explode) {
        this.explodeGrenade(p.mesh.position.clone());
        this.scene.remove(p.mesh); this.projectiles.splice(i, 1);
      }
    }

    // sway/bob/recoil animation
    const yawDelta = this.player.yaw - this.prevYaw;
    const pitchDelta = this.player.pitch - this.prevPitch;
    this.prevYaw = this.player.yaw; this.prevPitch = this.player.pitch;
    this.swayX = lerp(this.swayX, clamp(-yawDelta * 0.7, -0.035, 0.035), clamp(dt * 9, 0, 1));
    this.swayY = lerp(this.swayY, clamp(pitchDelta * 0.6, -0.03, 0.03), clamp(dt * 9, 0, 1));
    this.bobTime += dt * (this.player.moving ? (this.player.sprinting ? 11 : 7.2) : 1.4);
    const bobK = this.player.ads ? 0.15 : 1;
    const bobX = Math.sin(this.bobTime) * 0.006 * bobK * (this.player.moving ? 1 : 0.25);
    const bobY = Math.abs(Math.cos(this.bobTime)) * 0.005 * bobK * (this.player.moving ? 1 : 0.25);

    this.recoilVisualVel += (-this.recoilVisual * 150 - this.recoilVisualVel * 18) * dt;
    this.recoilVisual += this.recoilVisualVel * dt;
    this.kickZ = lerp(this.kickZ, 0, clamp(dt * 12, 0, 1));

    const hip = this.def.hip, ads = this.def.ads;
    let px = lerp(hip.x, ads.x, this.aimT) + this.swayX + bobX;
    let py = lerp(hip.y, ads.y, this.aimT) + this.swayY + bobY;
    let pz = lerp(hip.z, ads.z, this.aimT) + this.kickZ;
    let rx = lerp(this.def.hipRot.x, 0, this.aimT) + this.recoilVisual * 0.6;
    let ry = lerp(this.def.hipRot.y, 0, this.aimT) + this.swayX * 1.6;
    let rz = lerp(this.def.hipRot.z, 0, this.aimT) + this.swayX * 0.8;

    // reload animation pose
    if (this.reloading) {
      const k = clamp(this.reloadT / this.def.reloadTime, 0, 1);
      const s = Math.sin(clamp(k * 1.05, 0, 1) * Math.PI);
      py -= 0.10 * s; px += 0.03 * s; pz += 0.03 * s;
      rx += 0.55 * s; rz -= 0.35 * s; ry += 0.25 * s;
    }
    // switch animation
    if (this.switching) {
      const k = clamp(this.switchT / this.def.switchTime, 0, 1);
      const s = Math.sin(k * Math.PI);
      py -= 0.22 * s; rx += 0.7 * s;
    }
    // sprint pose
    if (this.player.sprinting && this.player.speed > 5) {
      px += 0.025; ry -= 0.22; rz += 0.1; rx -= 0.06;
    }

    this.holder.position.set(px, py, pz);
    this.holder.rotation.set(rx, ry, rz);

    // muzzle flash point light flicker handled by fx
    this.flashlight.intensity = 20 + Math.sin(performance.now() * 0.02) * 0.6;

    // crosshair spread
    const moveFactor = clamp(this.player.speed / 7, 0, 1);
    const spread = lerp(this.def.hipSpread, this.def.adsSpread, this.aimT) + moveFactor * this.def.moveSpread * (1 - this.aimT * 0.7);
    this.hud?.setSpread(spread, this.aimT, this.player.sprinting);
  }

  getForward() {
    const d = new THREE.Vector3(); this.camera.getWorldDirection(d); return d;
  }
}

import * as THREE from 'three';

const rand = (a, b) => a + Math.random() * (b - a);
const clamp = (x, a, b) => Math.max(a, Math.min(b, x));
const lerp = (a, b, t) => a + (b - a) * t;

const TYPES = {
  grunt: { health: 100, speed: 2.55, damage: 9, interval: 1.7, accuracy: 0.46, preferred: 11, scale: 1, score: 100, burst: 1 },
  scout: { health: 68, speed: 3.65, damage: 7, interval: 1.25, accuracy: 0.42, preferred: 8, scale: 0.94, score: 130, burst: 1 },
  heavy: { health: 950, speed: 1.65, damage: 13, interval: 2.15, accuracy: 0.52, preferred: 14, scale: 1.48, score: 1200, burst: 4 },
};

function raySphere(origin, dir, center, radius) {
  const ox = origin.x - center.x, oy = origin.y - center.y, oz = origin.z - center.z;
  const b = ox * dir.x + oy * dir.y + oz * dir.z;
  const c = ox * ox + oy * oy + oz * oz - radius * radius;
  const disc = b * b - c;
  if (disc < 0) return null;
  const sq = Math.sqrt(disc);
  let t = -b - sq;
  if (t < 0) t = -b + sq;
  return t > 0 ? t : null;
}

export class EnemyManager {
  constructor(scene, world, fx, audio, hud, player) {
    this.scene = scene; this.world = world; this.fx = fx; this.audio = audio; this.hud = hud; this.player = player;
    this.enemies = [];
    this.queue = [];
    this.spawnTimer = 0;
    this.wave = 0;
    this.maxAlive = 6;
    this.active = false;
    this.spawnInterval = 1;
    this.boss = null;
    this.kills = 0;
    this.headshots = 0;
    this.onKill = null;
    this.onWaveCleared = null;
    this.onBossSpawn = null;
    this.onAllDead = null;
    this._pendingBoss = false;
    this.time = 0;
    this._tmp = new THREE.Vector3();
    this._camRight = new THREE.Vector3();
  }

  reset() {
    for (const e of this.enemies) this._remove(e);
    this.enemies = [];
    this.queue = [];
    this.wave = 0; this.active = false; this.spawnTimer = 0;
    this.boss = null; this.kills = 0; this.headshots = 0;
    this._pendingBoss = false;
  }

  get remaining() {
    let alive = 0;
    for (const e of this.enemies) if (!e.dead) alive++;
    return alive + this.queue.length;
  }
  get aliveCount() {
    let a = 0; for (const e of this.enemies) if (!e.dead) a++;
    return a;
  }

  startWave(n) {
    this.wave = n; this.active = true;
    this.maxAlive = Math.min(3 + n, 7);
    this.spawnInterval = Math.max(0.55, 1.25 - n * 0.09);
    const q = [];
    const push = (type, count) => { for (let i = 0; i < count; i++) q.push(type); };
    if (n === 1) push('grunt', 4);
    else if (n === 2) { push('grunt', 5); push('scout', 1); }
    else if (n === 3) { push('grunt', 6); push('scout', 2); }
    else if (n === 4) { push('grunt', 7); push('scout', 3); }
    else if (n === 5) { push('grunt', 6); push('scout', 2); push('heavy', 1); }
    else { push('grunt', 8 + n); push('scout', 2); }
    // shuffle but keep boss last
    const boss = q.filter(t => t === 'heavy');
    const rest = q.filter(t => t !== 'heavy');
    for (let i = rest.length - 1; i > 0; i--) { const j = (Math.random() * (i + 1)) | 0; [rest[i], rest[j]] = [rest[j], rest[i]]; }
    // ensure first few aren't all scouts
    this.queue = rest.concat(boss);
    this.spawnTimer = 0.2;
    this.active = true;
    this._spawnIndex = 0;
    return q.length;
  }

  spawn(type) {
    const def = TYPES[type];
    const g = this.buildSoldier(type);
    // choose spawn point far from player
    let point = null, bestD = -1;
    for (let i = 0; i < 4; i++) {
      const sp = this.world.spawnPoints[(Math.random() * this.world.spawnPoints.length) | 0];
      const wp = sp.clone().add(new THREE.Vector3(rand(-2, 2), 0, rand(-2, 2)));
      const d = wp.distanceTo(this.player.position);
      if (d > bestD && d > 14) { bestD = d; point = wp; }
    }
    if (!point) point = this.world.spawnPoints[0].clone();
    // nudge out of obstacles
    this.world.collide(point, 0.6, 1.8);
    g.position.copy(point);
    g.scale.setScalar(def.scale);
    g.rotation.y = Math.atan2(this.player.position.x - point.x, this.player.position.z - point.z);
    this.scene.add(g);
    const matList = [];
    g.traverse(o => { if (o.isMesh && o.material && o.material.emissive) matList.push(o.material); });

    const e = {
      type, def, group: g, position: point.clone(), yaw: g.rotation.y,
      health: def.health, maxHealth: def.health, dead: false, deathT: 0,
      fireTimer: rand(0.8, 1.8), burstLeft: 0, burstTimer: 0,
      state: 'spawn', spawnT: 0, walkPhase: rand(0, 6), strafeDir: Math.random() > 0.5 ? 1 : -1,
      strafeTimer: rand(1, 3), hitFlash: 0, flinch: 0, mats: matList, hits: 0,
      moveSpeed: def.speed * rand(0.9, 1.1), lastSeen: 0, fireAnim: 0,
      scale: def.scale, headOffset: 1.66, aimTime: 0, visible: true,
      patrolAngle: rand(0, 6.28),
    };
    e.root = g;
    e.legL = g.getObjectByName('legL'); e.legR = g.getObjectByName('legR');
    e.armL = g.getObjectByName('armL'); e.armR = g.getObjectByName('armR');
    e.gun = g.getObjectByName('gun');
    e.muzzle = new THREE.Object3D();
    if (e.gun) { e.muzzle.position.set(0, 0.08, -0.62); e.gun.add(e.muzzle); }
    else { e.muzzle.position.set(0.3, 1.35, 0.4); g.add(e.muzzle); }
    this.enemies.push(e);
    if (type === 'heavy') { this.boss = e; this.hud?.setBoss(e.health, e.maxHealth, true); this.onBossSpawn?.(e); }
    // spawn effect
    this.fx.spawnSmoke(point.clone().add(new THREE.Vector3(0, 1, 0)), new THREE.Vector3(0, 1, 0), 1.4, 1.2, 0.3);
    this.fx.spawnSparks(point.clone().add(new THREE.Vector3(0, 1.1, 0)), new THREE.Vector3(0, 1, 0), 8, 0xff4a33, 2.5);
    return e;
  }

  buildSoldier(type) {
    const heavy = type === 'heavy';
    const scout = type === 'scout';
    const g = new THREE.Group(); g.name = 'soldier';
    const uniform = new THREE.MeshStandardMaterial({ color: scout ? 0x272a26 : 0x2b2f2b, roughness: 0.92, metalness: 0.08 });
    const armor = new THREE.MeshStandardMaterial({ color: heavy ? 0x2a2624 : 0x1b1e1f, roughness: 0.55, metalness: 0.55 });
    const vest = new THREE.MeshStandardMaterial({ color: heavy ? 0x3a2522 : 0x373a30, roughness: 0.85, metalness: 0.2 });
    const dark = new THREE.MeshStandardMaterial({ color: 0x101213, roughness: 0.7, metalness: 0.3 });
    const helmet = new THREE.MeshStandardMaterial({ color: heavy ? 0x332725 : 0x232724, roughness: 0.6, metalness: 0.45 });
    const skin = new THREE.MeshStandardMaterial({ color: 0x8a735e, roughness: 0.9 });
    const visorMat = new THREE.MeshStandardMaterial({ color: 0x1a0503, emissive: heavy ? 0xff1a0a : 0xff3a1c, emissiveIntensity: 2.2, roughness: 0.3 });
    const redAccent = new THREE.MeshStandardMaterial({ color: 0x3a0e0b, emissive: 0x7a1008, emissiveIntensity: 0.35, roughness: 0.8 });
    const glove = new THREE.MeshStandardMaterial({ color: 0x191a18, roughness: 0.9 });

    const s = heavy ? 1.18 : 1;
    // legs (pivot at hip)
    for (const side of [-1, 1]) {
      const leg = new THREE.Group(); leg.name = side < 0 ? 'legL' : 'legR';
      leg.position.set(side * 0.13 * s, 0.92, 0);
      const thigh = new THREE.Mesh(new THREE.BoxGeometry(0.17 * s, 0.46 * s, 0.19 * s), uniform); thigh.position.y = -0.23 * s; leg.add(thigh);
      const knee = new THREE.Mesh(new THREE.BoxGeometry(0.18 * s, 0.1 * s, 0.2 * s), dark); knee.position.y = -0.46 * s; leg.add(knee);
      const shin = new THREE.Mesh(new THREE.BoxGeometry(0.145 * s, 0.42 * s, 0.16 * s), uniform); shin.position.y = -0.68 * s; leg.add(shin);
      const boot = new THREE.Mesh(new THREE.BoxGeometry(0.17 * s, 0.14 * s, 0.28 * s), dark); boot.position.set(0, -0.92 * s, 0.04 * s); leg.add(boot);
      // knee pad
      const pad = new THREE.Mesh(new THREE.BoxGeometry(0.16 * s, 0.12 * s, 0.06 * s), armor); pad.position.set(0, -0.48 * s, 0.1 * s); leg.add(pad);
      g.add(leg);
    }
    // torso
    const torso = new THREE.Mesh(new THREE.BoxGeometry(0.46 * s, 0.52 * s, 0.26 * s), uniform); torso.position.y = 1.22 * s; g.add(torso);
    const chest = new THREE.Mesh(new THREE.BoxGeometry(0.50 * s, 0.42 * s, 0.32 * s), vest); chest.position.y = 1.24 * s; g.add(chest);
    // pouches
    for (const x of [-0.16, 0, 0.16]) {
      const p = new THREE.Mesh(new THREE.BoxGeometry(0.11 * s, 0.13 * s, 0.06 * s), armor); p.position.set(x * s, 1.14 * s, 0.18 * s); g.add(p);
    }
    // belt
    const belt = new THREE.Mesh(new THREE.BoxGeometry(0.44 * s, 0.08 * s, 0.28 * s), dark); belt.position.y = 0.98 * s; g.add(belt);
    // backpack
    const pack = new THREE.Mesh(new THREE.BoxGeometry(0.34 * s, 0.38 * s, 0.16 * s), vest); pack.position.set(0, 1.26 * s, -0.2 * s); g.add(pack);
    const packTop = new THREE.Mesh(new THREE.BoxGeometry(0.26 * s, 0.09 * s, 0.18 * s), armor); packTop.position.set(0, 1.48 * s, -0.19 * s); g.add(packTop);
    // head
    const head = new THREE.Mesh(new THREE.BoxGeometry(0.185 * s, 0.19 * s, 0.19 * s), skin); head.position.y = 1.63 * s; g.add(head);
    const helm = new THREE.Mesh(new THREE.BoxGeometry(0.24 * s, 0.15 * s, 0.25 * s), helmet); helm.position.y = 1.735 * s; g.add(helm);
    const brim = new THREE.Mesh(new THREE.BoxGeometry(0.24 * s, 0.035 * s, 0.08 * s), helmet); brim.position.set(0, 1.69 * s, 0.13 * s); g.add(brim);
    const visor = new THREE.Mesh(new THREE.BoxGeometry(0.17 * s, 0.045 * s, 0.02 * s), visorMat); visor.position.set(0, 1.645 * s, 0.103 * s); g.add(visor);
    // mask
    const mask = new THREE.Mesh(new THREE.BoxGeometry(0.16 * s, 0.09 * s, 0.06 * s), dark); mask.position.set(0, 1.575 * s, 0.1 * s); g.add(mask);
    // headset earpieces
    for (const side of [-1, 1]) {
      const ear = new THREE.Mesh(new THREE.CylinderGeometry(0.045 * s, 0.045 * s, 0.035 * s, 8), dark);
      ear.rotation.z = Math.PI / 2; ear.position.set(side * 0.11 * s, 1.65 * s, 0); g.add(ear);
    }
    if (heavy) {
      const crest = new THREE.Mesh(new THREE.BoxGeometry(0.06, 0.06, 0.26), redAccent); crest.position.set(0, 1.81 * s, 0); g.add(crest);
      for (const side of [-1, 1]) {
        const shoulder = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.16, 0.3), armor);
        shoulder.position.set(side * 0.33, 1.48 * s, 0); shoulder.rotation.z = side * -0.25; g.add(shoulder);
        const plate = new THREE.Mesh(new THREE.BoxGeometry(0.04, 0.24, 0.34), redAccent);
        plate.position.set(side * 0.28, 1.31, 0); plate.rotation.z = side * -0.1; g.add(plate);
      }
    } else {
      // shoulder patches
      const patch = new THREE.Mesh(new THREE.BoxGeometry(0.08, 0.08, 0.02), redAccent);
      patch.position.set(-0.19 * s, 1.4 * s, 0.17 * s); g.add(patch);
    }
    // arms
    for (const side of [-1, 1]) {
      const arm = new THREE.Group(); arm.name = side < 0 ? 'armL' : 'armR';
      arm.position.set(side * 0.29 * s, 1.44 * s, 0);
      const upper = new THREE.Mesh(new THREE.BoxGeometry(0.14 * s, 0.32 * s, 0.16 * s), uniform); upper.position.y = -0.15 * s; arm.add(upper);
      const elbow = new THREE.Mesh(new THREE.BoxGeometry(0.15 * s, 0.16 * s, 0.17 * s), armor); elbow.position.y = -0.33 * s; arm.add(elbow);
      const fore = new THREE.Mesh(new THREE.BoxGeometry(0.115 * s, 0.3 * s, 0.13 * s), uniform); fore.position.y = -0.48 * s; fore.position.z = 0.02; arm.add(fore);
      const hand = new THREE.Mesh(new THREE.BoxGeometry(0.11 * s, 0.11 * s, 0.13 * s), glove); hand.position.set(0, -0.65 * s, 0.04); arm.add(hand);
      // pose arms forward holding rifle
      arm.rotation.x = side < 0 ? -1.15 : -1.28;
      arm.rotation.z = side * 0.18;
      g.add(arm);
    }
    // weapon
    const gun = new THREE.Group(); gun.name = 'gun';
    const gm = new THREE.MeshStandardMaterial({ color: 0x191c1e, metalness: 0.8, roughness: 0.4 });
    const gm2 = new THREE.MeshStandardMaterial({ color: 0x2b2e2a, metalness: 0.3, roughness: 0.7 });
    const receiver = new THREE.Mesh(new THREE.BoxGeometry(0.07, 0.1, heavy ? 0.8 : 0.55), gm); receiver.position.z = -0.1; gun.add(receiver);
    const barrel = new THREE.Mesh(new THREE.CylinderGeometry(0.017, 0.017, heavy ? 0.55 : 0.35, 8), gm); barrel.rotation.x = Math.PI / 2; barrel.position.set(0, 0.015, heavy ? -0.75 : -0.5); gun.add(barrel);
    const mag = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.18, 0.08), gm2); mag.position.set(0, -0.14, 0.0); mag.rotation.x = -0.2; gun.add(mag);
    const stock = new THREE.Mesh(new THREE.BoxGeometry(0.055, 0.09, 0.2), gm2); stock.position.z = 0.28; gun.add(stock);
    if (heavy) {
      const drum = new THREE.Mesh(new THREE.CylinderGeometry(0.14, 0.14, 0.12, 12), gm2); drum.rotation.z = Math.PI / 2; drum.position.set(0.09, -0.03, 0.05); gun.add(drum);
      const glow = new THREE.Mesh(new THREE.BoxGeometry(0.04, 0.02, 0.2), visorMat); glow.position.set(0, 0.07, -0.2); gun.add(glow);
    }
    gun.position.set(0.13 * s, 1.28 * s, 0.34 * s);
    gun.rotation.y = 0.04;
    g.add(gun);
    // muzzle flash sprite placeholder
    const flash = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.fx.glow, color: 0xffc070, transparent: true, opacity: 0, depthWrite: false, blending: THREE.AdditiveBlending }));
    flash.position.set(0, 0.015, heavy ? -1.02 : -0.72); flash.scale.set(0.35, 0.35, 1); gun.add(flash);
    g.userData.flash = flash;
    // eyes / visor glow sprite
    const glow = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.fx.glow, color: 0xff3a1a, transparent: true, opacity: 0.4, depthWrite: false, blending: THREE.AdditiveBlending }));
    glow.position.set(0, 1.645 * s, 0.12 * s); glow.scale.set(0.25, 0.15, 1); g.add(glow);
    g.traverse(o => { if (o.isMesh) { o.castShadow = true; o.receiveShadow = true; } });
    return g;
  }

  _remove(e) { this.scene.remove(e.group); }

  raycast(origin, dir, maxDist = 200) {
    let best = null;
    for (const e of this.enemies) {
      if (e.dead) continue;
      const p = e.position;
      const scale = e.scale;
      const head = this._tmp.set(p.x, p.y + e.headOffset * scale, p.z);
      const ht = raySphere(origin, dir, head, 0.19 * scale);
      if (ht !== null && ht < maxDist && (!best || ht < best.distance)) {
        best = { enemy: e, distance: ht, point: origin.clone().addScaledVector(dir, ht), head: true };
      }
      const torso = this._tmp.set(p.x, p.y + 1.18 * scale, p.z);
      const bt = raySphere(origin, dir, torso, 0.38 * scale);
      if (bt !== null && bt < maxDist && (!best || bt < best.distance)) {
        best = { enemy: e, distance: bt, point: origin.clone().addScaledVector(dir, bt), head: false };
      }
      const legs = this._tmp.set(p.x, p.y + 0.62 * scale, p.z);
      const lt = raySphere(origin, dir, legs, 0.32 * scale);
      if (lt !== null && lt < maxDist && (!best || lt < best.distance)) {
        best = { enemy: e, distance: lt, point: origin.clone().addScaledVector(dir, lt), head: false };
      }
    }
    return best;
  }

  damage(e, amount, head, point, dir) {
    if (!e || e.dead) return false;
    e.health -= amount;
    e.hitFlash = 0.14;
    e.flinch = 0.18;
    if (head) { e.stagger = 0.3; }
    // alert
    if (e.state === 'spawn') e.state = 'seek';
    e.fireTimer = Math.min(e.fireTimer, 0.6);
    if (e === this.boss) this.hud?.setBoss(Math.max(0, e.health), e.maxHealth, true);
    if (e.health <= 0) {
      this.kill(e, head, point, dir);
      return true;
    }
    return false;
  }

  kill(e, head, point, dir) {
    if (e.dead) return;
    e.dead = true; e.deathT = 0; e.health = 0;
    e.group.userData.flash.material.opacity = 0;
    this.kills++; if (head) this.headshots++;
    this.fx.spawnBlood(point || e.position.clone().add(new THREE.Vector3(0, 1.2, 0)), dir || new THREE.Vector3(0, 1, 0), head ? 22 : 12);
    this.fx.spawnSparks(e.position.clone().add(new THREE.Vector3(0, 1.2, 0)), new THREE.Vector3(0, 1, 0), 6, 0x9c1a10, 3);
    if (e === this.boss) { this.hud?.setBoss(0, e.maxHealth, false); }
    this.onKill?.(e, head);
  }

  damageRadius(p, radius, maxDamage) {
    for (const e of this.enemies) {
      if (e.dead) continue;
      const d = e.position.clone().setY(1).distanceTo(p);
      if (d < radius) {
        const dmg = maxDamage * (1 - d / radius);
        const dir = e.position.clone().sub(p).setY(0).normalize();
        this.fx.spawnBlood(e.position.clone().add(new THREE.Vector3(0, 1.2, 0)), dir, 10);
        this.damage(e, dmg, false, e.position.clone().add(new THREE.Vector3(0, 1.2, 0)), dir);
      }
    }
  }

  update(dt, camera) {
    this.time += dt;
    // spawn queue
    if (this.active) {
      this.spawnTimer -= dt;
      if (this.queue.length > 0 && this.aliveCount < this.maxAlive && this.spawnTimer <= 0) {
        const type = this.queue.shift();
        this.spawn(type);
        this.spawnTimer = this.spawnInterval * rand(0.8, 1.25);
      }
      if (this.queue.length === 0 && this.aliveCount === 0) {
        this.active = false;
        this.onAllDead?.(this.wave);
      }
    }

    for (const e of this.enemies) {
      if (e.dead) { this.updateDead(e, dt); continue; }
      this.updateAlive(e, dt, camera);
    }
    // remove long dead
    for (let i = this.enemies.length - 1; i >= 0; i--) {
      const e = this.enemies[i];
      if (e.dead && e.deathT > 7) { this._remove(e); this.enemies.splice(i, 1); }
    }
  }

  updateDead(e, dt) {
    e.deathT += dt;
    const k = clamp(e.deathT / 0.85, 0, 1);
    const er = 1 - Math.pow(1 - k, 2);
    e.group.rotation.x = -er * 1.35;
    e.group.position.y = e.position.y + Math.sin(k * Math.PI) * 0.05;
    if (e.deathT > 4.5) {
      e.group.position.y = e.position.y - (e.deathT - 4.5) * 0.12;
    }
    if (e.deathT > 6.5) e.group.visible = false;
  }

  updateAlive(e, dt, camera) {
    const player = this.player;
    if (e.hitFlash > 0) e.hitFlash -= dt;
    if (e.flinch > 0) e.flinch -= dt;
    if (e.stagger > 0) e.stagger -= dt;
    // material flash
    for (const m of e.mats) {
      if (!m.emissive) continue;
      if (e.hitFlash > 0) { m.emissive.setHex(0x661108); m.emissiveIntensity = 0.9; }
      else if (m !== this.player) { m.emissive.setHex(m.userData.baseEmissive ?? 0x000000); m.emissiveIntensity = m.userData.baseIntensity ?? 0; }
    }
    if (e.def.health > 300) {
      // boss stays angry-lit
    }

    if (e.state === 'spawn') {
      e.spawnT += dt;
      const k = clamp(e.spawnT / 0.55, 0, 1);
      e.group.scale.setScalar(e.scale * lerp(0.3, 1, k));
      e.group.position.y = e.position.y + (1 - k) * 0.5;
      if (k >= 1) { e.state = 'seek'; e.group.scale.setScalar(e.scale); }
      return;
    }
    const toPlayer = new THREE.Vector3(player.position.x - e.position.x, 0, player.position.z - e.position.z);
    const dist = toPlayer.length();
    toPlayer.normalize();
    const eye = new THREE.Vector3(e.position.x, e.position.y + 1.55 * e.scale, e.position.z);
    const playerEye = new THREE.Vector3(player.position.x, player.position.y + player.eyeCurrent, player.position.z);
    const los = dist < 34 && this.world.hasLOS(eye, playerEye);
    e.lastSeen = los ? 0 : e.lastSeen + dt;

    // face player when close / attacking
    const targetYaw = Math.atan2(player.position.x - e.position.x, player.position.z - e.position.z);
    let dy = targetYaw - e.yaw;
    while (dy > Math.PI) dy -= Math.PI * 2;
    while (dy < -Math.PI) dy += Math.PI * 2;
    e.yaw += dy * clamp(dt * (los ? 5 : 2.5), 0, 1);
    e.group.rotation.y = e.yaw;

    // movement
    let moveX = 0, moveZ = 0, moving = false;
    const preferred = e.def.preferred;
    if (e.stagger > 0) {
      // recoil in place
    } else if (!los || dist > preferred + 3) {
      moveX = toPlayer.x; moveZ = toPlayer.z; moving = true;
    } else if (dist < preferred - 4) {
      moveX = -toPlayer.x; moveZ = -toPlayer.z; moving = true;
    } else {
      // strafe around the player
      e.strafeTimer -= dt;
      if (e.strafeTimer <= 0) { e.strafeDir *= -1; e.strafeTimer = rand(1.4, 3.2); }
      moveX = -toPlayer.z * e.strafeDir * 0.7;
      moveZ = toPlayer.x * e.strafeDir * 0.7;
      moving = true;
    }
    // separation
    for (const other of this.enemies) {
      if (other === e || other.dead) continue;
      const dx = e.position.x - other.position.x, dz = e.position.z - other.position.z;
      const d2 = dx * dx + dz * dz;
      if (d2 < 2.2 && d2 > 0.001) { const d = Math.sqrt(d2); moveX += (dx / d) * 0.8; moveZ += (dz / d) * 0.8; }
    }
    const ml = Math.hypot(moveX, moveZ);
    if (ml > 0.001 && moving) {
      moveX /= ml; moveZ /= ml;
      const speed = e.moveSpeed * (los ? 0.75 : 1.15);
      const nx = e.position.x + moveX * speed * dt;
      const nz = e.position.z + moveZ * speed * dt;
      const before = e.position.clone();
      e.position.x = nx; e.position.z = nz;
      this.world.collide(e.position, 0.42 * e.scale, 1.8);
      // if stuck, steer
      if (Math.hypot(e.position.x - before.x, e.position.z - before.z) < speed * dt * 0.35) {
        e.strafeDir *= -1;
        const px = -toPlayer.z * e.strafeDir, pz = toPlayer.x * e.strafeDir;
        e.position.x = before.x + px * speed * dt;
        e.position.z = before.z + pz * speed * dt;
        this.world.collide(e.position, 0.42 * e.scale, 1.8);
      }
    }
    e.group.position.x = e.position.x;
    e.group.position.z = e.position.z;

    // footsteps / walk animation
    if (moving) {
      e.walkPhase += dt * (e.moveSpeed * 2.6);
      const swing = Math.sin(e.walkPhase) * 0.55;
      if (e.legL) e.legL.rotation.x = swing;
      if (e.legR) e.legR.rotation.x = -swing;
      if (e.armL) e.armL.rotation.x = -1.15 + Math.sin(e.walkPhase + Math.PI) * 0.08;
      if (e.armR) e.armR.rotation.x = -1.28 + Math.sin(e.walkPhase) * 0.05;
      e.group.position.y = e.position.y + Math.abs(Math.sin(e.walkPhase * 2)) * 0.025;
    } else {
      if (e.legL) e.legL.rotation.x = lerp(e.legL.rotation.x, 0, dt * 6);
      if (e.legR) e.legR.rotation.x = lerp(e.legR.rotation.x, 0, dt * 6);
      e.group.position.y = e.position.y;
    }

    // shooting
    e.fireAnim = Math.max(0, e.fireAnim - dt * 6);
    const flash = e.group.userData.flash;
    if (flash) flash.material.opacity = e.fireAnim > 0.5 ? 1 : 0;
    if (los && dist < 36 && e.stagger <= 0 && !e.dead) {
      e.state = 'attack';
      e.fireTimer -= dt;
      if (e.fireTimer <= 0) {
        if (e.burstLeft <= 0) e.burstLeft = e.def.burst;
        this.enemyShoot(e, dist, camera);
        e.burstLeft--;
        e.fireAnim = 1;
        if (e.burstLeft > 0) e.fireTimer = 0.13;
        else e.fireTimer = e.def.interval * rand(0.8, 1.3);
      }
    } else {
      e.fireTimer = Math.max(e.fireTimer - dt, 0);
    }
    // flinch
    if (e.flinch > 0) e.group.rotation.z = Math.sin(e.flinch * 80) * 0.025;
    else e.group.rotation.z = 0;
  }

  enemyShoot(e, dist, camera) {
    const origin = e.muzzle.getWorldPosition(new THREE.Vector3());
    const target = new THREE.Vector3(this.player.position.x, this.player.position.y + 1.2, this.player.position.z);
    const toTarget = target.clone().sub(origin);
    const len = toTarget.length(); toTarget.divideScalar(len);
    // accuracy affected by distance and player movement
    let chance = e.def.accuracy * clamp(1.2 - dist / 55, 0.35, 1.1);
    if (this.player.sprinting) chance *= 0.62;
    if (this.player.speed > 2) chance *= 0.8;
    if (this.player.ads) chance *= 0.9;
    const hit = Math.random() < chance;
    let end;
    if (hit) {
      end = target.clone();
      const dmg = e.def.damage * rand(0.8, 1.2);
      this.player.takeDamage(dmg, e.position);
      // tracer appears to pass
      end.add(new THREE.Vector3(rand(-0.2, 0.2), rand(-0.1, 0.1), rand(-0.2, 0.2)));
    } else {
      const miss = new THREE.Vector3(rand(-1.2, 1.2), rand(-0.4, 1.0), rand(-1.2, 1.2));
      end = target.clone().add(miss);
      // check if misses hit environment
      const env = this.world.raycast(origin, toTarget, len);
      if (env) { end = env.point; this.fx.impact(env.point, this.fxNormal(env), 'concrete'); }
    }
    this.fx.tracer(origin, end, 0xffb090, 1);
    this.fx.muzzleFlash(origin, toTarget, e.scale * 0.8, 0xffb36a);
    // pan by angle relative to camera
    const right = new THREE.Vector3(1, 0, 0).applyQuaternion(camera.quaternion);
    const rel = origin.clone().sub(camera.position);
    const pan = clamp(rel.normalize().dot(right), -1, 1);
    this.audio?.enemyShot?.(dist, pan);
  }

  fxNormal(hit) {
    if (hit.collider === 'ground') return new THREE.Vector3(0, 1, 0);
    const c = hit.collider, p = hit.point;
    const eps = 0.03;
    if (Math.abs(p.x - c.x1) < eps) return new THREE.Vector3(-1, 0, 0);
    if (Math.abs(p.x - c.x2) < eps) return new THREE.Vector3(1, 0, 0);
    if (Math.abs(p.z - c.z1) < eps) return new THREE.Vector3(0, 0, -1);
    if (Math.abs(p.z - c.z2) < eps) return new THREE.Vector3(0, 0, 1);
    return new THREE.Vector3(0, 1, 0);
  }
}

