219:     this.ammo = { rifle: { mag: 30, reserve: 180 }, pistol: { mag: 12, reserve: Infinity } };
220:     this.grenades = 3;
221:     this.reloading = false; this.reloadT = 0; this.reloadStage = 0;
222:     this.switching = false; this.fireTimer = 0;
223:     this.aimT = 0; this.recoilVisual = 0; this.recoilVisualVel = 0; this.kickZ = 0;
224:     this.swayX = 0; this.swayY = 0;
225:     this.shotsFired = 0; this.shotsHit = 0; this.headshots = 0;
226:     this.rifle.visible = true; this.pistol.visible = false;
227:     this.projectiles.forEach(p => this.scene.remove(p.mesh)); this.projectiles = [];
228:     this.hud?.setGrenades(this.grenades);
229:     this.hud?.setWeapon(this.defs.rifle.name, this.defs.rifle.mode);
230:     this.hud?.setAmmo(this.ammo.rifle.mag, this.ammo.rifle.reserve);
