236:   setEnabled(on) {
237:     this.enabled = on;
238:     this.holder.visible = on;
239:     this.flashlight.visible = on;
240:     if (this.viewLights) for (const l of this.viewLights) l.visible = on;
241:     this.player.fovTarget = on ? 78 : this.player.fovTarget;
242:     if (!on) { this.pistol.visible = false; this.rifle.visible = true; }
