244: 
245:   get def() { return this.defs[this.current]; }
246:   get ammoNow() { return this.ammo[this.current]; }
247: 
248:   addReserve(amount) {
249:     for (const k of ['rifle', 'pistol']) {
250:       if (this.ammo[k].reserve === Infinity) continue;
251:       this.ammo[k].reserve = Math.min(this.defs[k].reserveMax, this.ammo[k].reserve + amount);
252:     }
253:     this.hud?.setAmmo(this.ammoNow.mag, this.ammoNow.reserve);
254:   }
255: 
256:   addGrenades(n) { this.grenades = Math.min(this.maxGrenades, this.grenades + n); this.hud?.setGrenades(this.grenades); }
257: 
258:   key(code) {
259:     if (!this.enabled) return;
260:     if (code === 'KeyR') this.reload();
261:     if (code === 'Digit1') this.switchTo('rifle');
262:     if (code === 'Digit2') this.switchTo('pistol');
263:     if (code === 'KeyG') this.throwGrenade();
264:     if (code === 'KeyQ') this.switchTo(this.current === 'rifle' ? 'pistol' : 'rifle');
265:   }
266: 
267:   reload() {
268:     if (this.reloading || this.switching) return;
269:     if (this.ammoNow.mag >= this.def.magSize) return;
270:     if (this.ammoNow.reserve !== Infinity && this.ammoNow.reserve <= 0) return;
271:     this.reloading = true; this.reloadT = 0; this.reloadStage = 0;
272:     this.hud?.setReloading(true, this.def.reloadTime);
273:     this.audio?.reload?.(0);
274:   }
275: 
276:   switchTo(id) {
277:     if (id === this.current || this.switching) return;
278:     this.switching = true; this.switchT = 0; this.switchTarget = id; this.switchStage = 0;
279:     this.reloading = false; this.hud?.setReloading(false);
280:     this.audio?.switchWeapon?.();
281:   }
282: 
283:   switchImmediate(id) {
284:     this.current = id;
285:     this.rifle.visible = id === 'rifle'; this.pistol.visible = id === 'pistol';
286:     const d = this.def;
287:     this.hud?.setWeapon(d.name, d.mode);
288:     this.hud?.setAmmo(this.ammoNow.mag, this.ammoNow.reserve);
289:     this.hud?.setSlot(id);
290:     this.player.fovTarget = 78;
291:   }
292: 
293:   finishReload() {
294:     const a = this.ammoNow;
295:     const need = this.def.magSize - a.mag;
296:     if (a.reserve === Infinity) a.mag = this.def.magSize;
297:     else { const take = Math.min(need, a.reserve); a.mag += take; a.reserve -= take; }
298:     this.reloading = false;
299:     this.hud?.setReloading(false);
300:     this.hud?.setAmmo(a.mag, a.reserve);
301:   }
302: 
303:   throwGrenade() {
304:     if (!this.enabled || this.grenadeCooldown > 0 || this.grenades <= 0) return;
305:     this.grenades--; this.hud?.setGrenades(this.grenades); this.grenadeCooldown = 1.1;
306:     this.audio?.throwGrenade?.();
307:     const dir = new THREE.Vector3(); this.camera.getWorldDirection(dir);
308:     const pos = this.camera.position.clone().addScaledVector(dir, 0.45).add(new THREE.Vector3(0, -0.12, 0));
309:     const mesh = new THREE.Mesh(new THREE.SphereGeometry(0.055, 10, 8), new THREE.MeshStandardMaterial({ color: 0x39412c, roughness: 0.6, metalness: 0.4 }));
310:     const band = new THREE.Mesh(new THREE.TorusGeometry(0.056, 0.008, 4, 12), new THREE.MeshStandardMaterial({ color: 0x8f2f1a }));
311:     band.rotation.x = Math.PI / 2; mesh.add(band);
312:     mesh.position.copy(pos); this.scene.add(mesh);
313:     const vel = dir.clone().multiplyScalar(15).add(new THREE.Vector3(0, 4.2, 0));
314:     this.projectiles.push({ mesh, vel, life: 2.7, trail: 0, exploded: false });
315:     this.player.addShake(0.04);
316:     this.hud?.hint('FRAG OUT');
317:   }
318: 
319:   explodeGrenade(p) {
320:     this.fx.explosion(p, 8);
321:     this.player.addShake(0.85);
322:     const pd = this.player.position.clone().setY(1).distanceTo(p);
323:     if (pd < 8) this.player.takeDamage(Math.round(70 * (1 - pd / 8)), p);
324:     this.enemies?.damageRadius?.(p, 8, 130);
325:   }
326: 
327:   fire() {
328:     if (!this.enabled || this.reloading || this.switching || this.fireTimer > 0) return;
329:     const a = this.ammoNow;
330:     if (a.mag <= 0) { this.audio?.dryFire?.(); this.fireTimer = 0.18; this.reload(); return; }
331:     const def = this.def;
332:     a.mag--; this.shotsFired++;
333:     this.fireTimer = 60 / def.rpm;
334:     if (def.auto) this.triggerHeld = true;
335:     this.hud?.setAmmo(a.mag, a.reserve);
336: 
337:     const aim = this.aimT;
338:     const moveFactor = clamp(this.player.speed / 7, 0, 1);
339:     const spread = lerp(def.hipSpread, def.adsSpread, aim) + moveFactor * def.moveSpread * (1 - aim * 0.7);
340:     const dir = new THREE.Vector3(); this.camera.getWorldDirection(dir);
341:     const right = new THREE.Vector3(1, 0, 0).applyQuaternion(this.camera.quaternion);
342:     const up = new THREE.Vector3(0, 1, 0).applyQuaternion(this.camera.quaternion);
343:     const ang = Math.random() * Math.PI * 2, rad = Math.sqrt(Math.random()) * spread;
344:     dir.addScaledVector(right, Math.cos(ang) * rad).addScaledVector(up, Math.sin(ang) * rad).normalize();
345: 
346:     // muzzle position in world
347:     const muzzleObj = this.current === 'rifle' ? this.rifle : this.pistol;
348:     const muzzleLocal = this.current === 'rifle' ? new THREE.Vector3(...def.muzzle) : new THREE.Vector3(...def.muzzle);
349:     const muzzle = muzzleObj.localToWorld(muzzleLocal.clone());
350:     if (this.current === 'rifle' && this.rifleMag && !this.rifleMag.visible) this.rifleMag.visible = true;
351: 
352:     const maxDist = 180;
353:     const envHit = this.world.raycast(this.camera.position, dir, maxDist);
354:     const enemyHit = this.enemies?.raycast(this.camera.position, dir, envHit ? envHit.distance : maxDist);
355:     let end;
356:     if (enemyHit) {
357:       end = enemyHit.point;
358:       const falloff = clamp(1 - Math.max(0, enemyHit.distance - 28) / 90, 0.7, 1);
359:       const isHead = enemyHit.head;
360:       const dmg = def.damage * falloff * (isHead ? def.headMul : 1);
361:       const killed = this.enemies.damage(enemyHit.enemy, dmg, isHead, enemyHit.point, dir);
362:       this.shotsHit++;
363:       if (isHead) this.headshots++;
364:       this.fx.spawnBlood(enemyHit.point, dir, isHead ? 12 : 7);
365:       this.hud?.hitmarker(isHead, killed);
366:       this.audio?.hit?.(isHead);
367:     } else if (envHit) {
368:       end = envHit.point;
369:       const mat = this.surfaceOf(envHit.collider);
370:       const n = this.normalFor(envHit);
371:       this.fx.impact(end, n, mat);
372:     } else {
373:       end = this.camera.position.clone().addScaledVector(dir, maxDist);
374:     }
375:     this.fx.tracer(muzzle, end, this.current === 'rifle' ? 0xffd9a0 : 0xffe6c2);
376:     this.fx.muzzleFlash(muzzle, dir, this.current === 'rifle' ? 1 : 0.75);
377:     this.audio.shot(this.current);
378:     this.player.addShake(this.aimT > 0.5 ? 0.045 : 0.095);
379:     const recoilMul = this.aimT > 0.5 ? def.adsRecoilMul : 1;
380:     this.player.addRecoil(def.recoil * recoilMul * (this.current === 'rifle' ? rand(0.85, 1.15) : 1), def.recoilYaw * rand(-1, 1) * (this.aimT > 0.5 ? 0.5 : 1));
381:     this.recoilVisualVel += def.recoil * 11 * recoilMul;
382:     this.kickZ += 0.028 * recoilMul;
383: 
384:     // eject shell
385:     this.shellTimer = 0.01;
386:     if (a.mag === 0) this.audio?.dryFire?.();
387:   }
388: 
389:   surfaceOf(collider) {
390:     const name = collider?.mesh?.name || '';
391:     if (name.includes('crate')) return 'wood';
392:     if (name) return 'concrete';
393:     return Math.random() > 0.5 ? 'metal' : 'concrete';
394:   }
395: 
396:   normalFor(hit) {
397:     if (hit.collider === 'ground') return new THREE.Vector3(0, 1, 0);
398:     const c = hit.collider, p = hit.point;
399:     const eps = 0.03;
400:     if (Math.abs(p.x - c.x1) < eps) return new THREE.Vector3(-1, 0, 0);
401:     if (Math.abs(p.x - c.x2) < eps) return new THREE.Vector3(1, 0, 0);
402:     if (Math.abs(p.z - c.z1) < eps) return new THREE.Vector3(0, 0, -1);
403:     if (Math.abs(p.z - c.z2) < eps) return new THREE.Vector3(0, 0, 1);
404:     return new THREE.Vector3(0, 1, 0);
405:   }
406: 
407:   update(dt) {
408:     if (!this.enabled) { this.holder.visible = false; this.flashlight.visible = false; return; }
409:     this.holder.visible = true; this.flashlight.visible = true;
410:     const input = this.input;
411:     this.fireTimer = Math.max(0, this.fireTimer - dt);
412:     this.grenadeCooldown = Math.max(0, this.grenadeCooldown - dt);
413: 
414:     // aim
415:     const canAim = !this.reloading && !this.switching && !this.player.sprinting;
416:     const wantAim = input.aim && canAim;
417:     this.aimT = lerp(this.aimT, wantAim ? 1 : 0, clamp(dt * 13, 0, 1));
418:     this.player.ads = this.aimT > 0.5;
419:     this.player.fovTarget = lerp(78, this.def.adsFov, this.aimT);
420:     this.hud?.setAim(this.aimT);
421: 
422:     // fire
423:     if (input.fire) {
424:       if (!this.triggerHeld || this.def.auto) this.fire();
425:       this.triggerHeld = true;
426:     } else this.triggerHeld = false;
427: 
428:     // reload progress
429:     if (this.reloading) {
430:       this.reloadT += dt;
431:       const k = this.reloadT / this.def.reloadTime;
432:       if (k >= 0.28 && this.reloadStage === 0) {
433:         this.reloadStage = 1; this.audio?.reload?.(1);
434:         if (this.rifleMag) this.rifleMag.position.y -= 0.18;
435:       }
