13: function raySphere(origin, dir, center, radius) {
14:   const ox = origin.x - center.x, oy = origin.y - center.y, oz = origin.z - center.z;
15:   const b = ox * dir.x + oy * dir.y + oz * dir.z;
16:   const c = ox * ox + oy * oy + oz * oz - radius * radius;
17:   const disc = b * b - c;
18:   if (disc < 0) return null;
19:   const sq = Math.sqrt(disc);
20:   let t = -b - sq;
21:   if (t < 0) t = -b + sq;
22:   return t > 0 ? t : null;
23: }
