import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.on('pageerror', e => console.log('PAGEERROR:', e.message));
await page.goto('http://localhost:3002/', { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(4000);
await page.getByLabel('Play Now').click();
await page.waitForTimeout(5000);
const info = await page.evaluate(() => {
  const n = window.__nightfall, g = n.game;
  g.enemies.reset();
  g.pendingWave = 0; g.waveActive = false; g.intermission = 999;
  g.player.position.set(0, 0, 14); g.player.yaw = 0; g.player.pitch = -0.05;
  const mk = (t, x, z) => { const e = g.enemies.spawn(t); e.position.set(x, 0, z); e.group.position.set(x, 0, z); e.state = 'idle'; e.spawnT = 1; e.group.scale.setScalar(e.scale); };
  mk('grunt', -3, 4); mk('grunt', 3, 3); mk('scout', 0, 1);
  g.player.godMode = true;
  return { obj: g.world.scene.children.length, pos: g.player.position.toArray(), cam: g.camera.position.toArray() };
});
console.log(info);
await page.waitForTimeout(2500);
await page.screenshot({ path: '/tmp/opencode/shots/d-normal.jpg', type: 'jpeg', quality: 82 });
const count = await page.evaluate(() => {
  const g = window.__nightfall.game;
  let n = 0; g.world.scene.traverse(o => { if (o.isSprite) n++; });
  return n;
});
console.log('sprites', count);
// hide weapon holder
await page.evaluate(() => { window.__nightfall.game.weapons.holder.visible = false; });
await page.waitForTimeout(500);
await page.screenshot({ path: '/tmp/opencode/shots/d-nogun.jpg', type: 'jpeg', quality: 82 });
// hide all sprites + transparent additive meshes
await page.evaluate(() => {
  const g = window.__nightfall.game;
  g.weapons.holder.visible = true;
  g.world.scene.traverse(o => { if (o.isSprite) o.visible = false; });
});
await page.waitForTimeout(500);
await page.screenshot({ path: '/tmp/opencode/shots/d-nosprite.jpg', type: 'jpeg', quality: 82 });
await browser.close();

