await page.waitForTimeout(4000);
await page.getByLabel('Play Now').click();
await page.waitForTimeout(5000);
const list = await page.evaluate(() => {
  const g = window.__nightfall.game;
  const cam = g.camera;
  cam.updateMatrixWorld(true);
  const cw = cam.matrixWorld.elements;
  const cx = cw[12], cy = cw[13], cz = cw[14];
  const right = [cw[0], cw[1], cw[2]];
  const up = [cw[4], cw[5], cw[6]];
  const fwd = [-cw[8], -cw[9], -cw[10]];
  const out = [];
  const proj = (x, y, z) => {
    const dx = x - cx, dy = y - cy, dz = z - cz;
    const f = dx * fwd[0] + dy * fwd[1] + dz * fwd[2];
    if (f <= 0.1) return null;
    const r = dx * right[0] + dy * right[1] + dz * right[2];
    const u = dx * up[0] + dy * up[1] + dz * up[2];
    return [Math.round(640 + (r / f) * 640 / Math.tan(39 * Math.PI / 180)), Math.round(400 - (u / f) * 400 / Math.tan(39 * Math.PI / 180)), Math.round(f)];
  };
  g.world.scene.updateMatrixWorld(true);
  const add = (o, k) => {
    const e = o.matrixWorld.elements;
    const x = e[12], y = e[13], z = e[14];
    const dist = Math.hypot(x - cx, y - cy, z - cz);
    if (dist > 30) return;
    const sp = proj(x, y, z);
    out.push({ k, color: o.material?.color?.getHexString?.() || o.color?.getHexString?.(), op: o.material?.opacity ?? null, int: o.intensity ?? null, scale: o.scale?.toArray?.().map(n => +n.toFixed(2)), pos: [x, y, z].map(n => +n.toFixed(2)), dist: +dist.toFixed(1), screen: sp, visible: o.visible });
  };
  g.world.scene.traverse(o => {
    if (o.isSprite) add(o, 'sprite');
    if (o.isPointLight || o.isSpotLight) add(o, o.type);
  });
  return out.sort((a, b) => a.dist - b.dist);
});
for (const o of list) console.log(JSON.stringify(o));
await browser.close();

