import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.on('pageerror', e => console.log('PAGEERROR:', e.message));
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE:', m.text()); });
await page.goto('http://localhost:3002/', { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(4000);
await page.getByLabel('Play Now').click();
await page.waitForTimeout(5000);
console.log(await page.evaluate(() => {
  const g = window.__nightfall.game, w = g.weapons;
  w.holder.updateMatrixWorld(true);
  const e = w.holder.matrixWorld.elements;
  return {
    state: g.state, enabled: w.enabled, visible: w.holder.visible,
    holderPos: [e[12], e[13], e[14]], holderScale: w.holder.scale.toArray(),
    camPos: g.camera.position.toArray(), camRot: [g.camera.rotation.x, g.camera.rotation.y],
    rifleVisible: w.rifle.visible, rifleChildren: w.rifle.children.length,
    rifleWorld: w.rifle.getWorldPosition ? w.rifle.matrixWorld.elements.slice(12, 15) : null,
    aimT: w.aimT, fov: g.camera.fov, near: g.camera.near,
    hudAim: document.getElementById('crosshair')?.style.opacity,
  };
}));
await page.screenshot({ path: '/tmp/opencode/shots/gun-check.jpg', type: 'jpeg', quality: 85 });
// top-down-ish close: raise gun in view by moving holder center
await page.evaluate(() => { const w = window.__nightfall.game.weapons; w.holder.position.set(0, -0.15, -0.5); w.holder.rotation.set(0, 0, 0); });
await page.waitForTimeout(700);
console.log(await page.evaluate(() => {
  const w = window.__nightfall.game.weapons;
  return { visible: w.holder.visible, pos: w.holder.position.toArray(), world: w.holder.matrixWorld.elements.slice(12, 15) };
}));
await page.screenshot({ path: '/tmp/opencode/shots/gun-center.jpg', type: 'jpeg', quality: 85 });
await browser.close();

