input.content:
import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.on('pageerror', e => console.log('PAGEERROR:', e.message));
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE:', m.text()); });
await page.goto('http://localhost:3002/', { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(4000);
await page.getByLabel('Play Now').click();
await page.waitForTimeout(5500);
console.log(await page.evaluate(() => window.__nightfall.state_info()));
await page.screenshot({ path: '/tmp/opencode/shots/q1.jpg', type: 'jpeg', quality: 85 });
await page.evaluate(() => {
  const g = window.__nightfall.game;
  g.player.godMode = true;
  g.player.position.set(0, 0, 17);
  g.player.yaw = 0; g.player.pitch = -0.02;
  const mk = (t, x, z) => { const e = g.enemies.spawn(t); e.position.set(x, 0, z); e.group.position.set(x, 0, z); e.state = 'seek'; e.spawnT = 1; e.group.scale.setScalar(e.scale); };
  mk('grunt', -2.5, 10); mk('grunt', 2.8, 8.5); mk('scout', 0.5, 6.5);
  g.enemies.maxAlive = 3;
});
await page.waitForTimeout(2200);
await page.screenshot({ path: '/tmp/opencode/shots/q2.jpg', type: 'jpeg', quality: 85 });
await page.evaluate(() => { const g = window.__nightfall.game; g.weapons.aimT = 1; g.weapons.update(0.016); });
await page.waitForTimeout(600);
await page.screenshot({ path: '/tmp/opencode/shots/q3.jpg', type: 'jpeg', quality: 85 });
await browser.close();

