import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.on('pageerror', e => console.log('PAGEERROR:', e.message));
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE:', m.text()); });
await page.goto('http://localhost:3002/', { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(4000);
await page.getByLabel('Play Now').click();
await page.waitForTimeout(5000);
await page.evaluate(() => {
  const g = window.__nightfall.game;
  g.player.godMode = true;
  g.enemies.reset();
  g.pendingWave = 0; g.waveActive = false; g.intermission = 999;
  g.player.position.set(0, 0, 17); g.player.yaw = 0; g.player.pitch = -0.03;
  const mk = (t, x, z, yaw) => {
    const e = g.enemies.spawn(t);
    e.position.set(x, 0, z); e.group.position.set(x, 0, z);
    e.state = 'idle'; e.spawnT = 1; e.group.scale.setScalar(e.scale);
    e.group.rotation.y = yaw === undefined ? Math.PI : yaw;
    e.moveSpeed = 0; e.def = { ...e.def, preferred: 99, speed: 0 };
  };
  mk('grunt', -1.9, 11, Math.PI);
  mk('scout', 1.4, 12.2, Math.PI);
  mk('heavy', 4.0, 10.6, Math.PI);
  g.input.aim = false;
});
await page.waitForTimeout(1800);
await page.screenshot({ path: '/tmp/opencode/shots/e-hip.jpg', type: 'jpeg', quality: 85 });
await page.evaluate(() => { window.__nightfall.game.input.aim = true; });
await page.waitForTimeout(1200);
console.log(await page.evaluate(() => { const w = window.__nightfall.game.weapons; return { aim: w.aimT, fov: window.__nightfall.game.player.fovTarget }; }));
await page.screenshot({ path: '/tmp/opencode/shots/e-ads.jpg', type: 'jpeg', quality: 85 });
// closeup enemy only
await page.evaluate(() => {
  const g = window.__nightfall.game;
  g.input.aim = false;
  g.enemies.enemies.forEach(e => { if (e.type !== 'grunt') { e.group.visible = false; e.dead = true; } });
  const e = g.enemies.enemies.find(e => e.type === 'grunt');
  e.position.set(0.2, 0, 13.2); e.group.position.set(0.2, 0, 13.2); e.group.rotation.y = Math.PI;
  g.player.position.set(0, 0, 17); g.player.yaw = 0; g.player.pitch = 0.0;
});
await page.waitForTimeout(900);
await page.screenshot({ path: '/tmp/opencode/shots/e-close.jpg', type: 'jpeg', quality: 85 });
await browser.close();

