import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errs = [];
page.on('pageerror', e => { errs.push('PAGEERROR: ' + e.message); console.log('PAGEERROR:', e.message); });
page.on('console', m => { if (m.type() === 'error') { errs.push('CONSOLE: ' + m.text()); console.log('CONSOLE:', m.text()); } });
await page.goto('http://localhost:3002/', { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(3500);
await page.getByLabel('Play Now').click();
await page.waitForTimeout(4000);
const info = () => page.evaluate(() => window.__nightfall.state_info());
console.log('start', await info());
await page.evaluate(() => { window.__nightfall.game.player.godMode = true; });
for (let w = 1; w <= 5; w++) {
  // wait for wave active or force it
  for (let i = 0; i < 40; i++) {
    const s = await info();
    if (s.wave === w && s.active) break;
    if (s.pending === w && s.inter > 2) await page.evaluate(() => { window.__nightfall.game.intermission = 0.05; });
    if (s.pending === w && s.inter <= 2) await page.waitForTimeout(300);
    else await page.waitForTimeout(250);
  }
  const s = await info();
  console.log('wave', w, s);
  if (w === 5) {
    const boss = await page.evaluate(() => {
      const g = window.__nightfall.game;
      const b = g.enemies.enemies.find(e => e.type === 'heavy');
      if (!b) return null;
      g.player.position.set(0, 0, 16); g.player.yaw = 0; g.player.pitch = 0;
      b.position.set(0, 0, 8); b.group.position.set(0, 0, 8); b.state = 'seek';
      return { health: b.health, bossBar: !document.getElementById('boss-bar').classList.contains('hidden') };
    });
    console.log('boss', boss);
    await page.waitForTimeout(700);
    await page.screenshot({ path: '/tmp/opencode/shots/v-boss.jpg', type: 'jpeg', quality: 85 });
  }
  await page.evaluate(() => window.__nightfall.killAll());
  await page.waitForTimeout(700);
  console.log('cleared', w, await info());
}
await page.waitForTimeout(3200);
console.log('win state', await page.evaluate(() => ({ state: window.__nightfall.game.state, overlay: !document.getElementById('gameover').classList.contains('hidden'), title: document.getElementById('result-title').textContent })));
await page.screenshot({ path: '/tmp/opencode/shots/v-win.jpg', type: 'jpeg', quality: 85 });
// redeploy
await page.getByRole('button', { name: /REDEPLOY/i }).click();
await page.waitForTimeout(2200);
// weapon checks
await page.evaluate(() => { const g = window.__nightfall.game; g.player.godMode = true; g.weapons.ammo.rifle.mag = 4; g.weapons.reload(); });
await page.waitForTimeout(2300);
const ammo1 = await page.evaluate(() => ({ mag: window.__nightfall.game.weapons.ammo.rifle.mag, reloading: window.__nightfall.game.weapons.reloading }));
console.log('reload', ammo1);
await page.evaluate(() => window.__nightfall.game.weapons.switchTo('pistol'));
await page.waitForTimeout(800);
const sw = await page.evaluate(() => ({ cur: window.__nightfall.game.weapons.current, name: document.getElementById('weapon-name').textContent, slot2: document.getElementById('slot-2').className }));
console.log('switch', sw);
const nade = await page.evaluate(() => { const g = window.__nightfall.game; const before = g.weapons.grenades; g.weapons.grenadeCooldown = 0; g.weapons.throwGrenade(); return { before, after: g.weapons.grenades, projectiles: g.weapons.projectiles.length }; });
console.log('nade', nade);
// pause
await page.keyboard.press('Escape');
await page.waitForTimeout(500);
console.log('paused', await page.evaluate(() => ({ state: window.__nightfall.game.state, overlay: !document.getElementById('pause').classList.contains('hidden') })));
await page.screenshot({ path: '/tmp/opencode/shots/v-pause.jpg', type: 'jpeg', quality: 85 });
await page.getByRole('button', { name: /RESUME/i }).click();
await page.waitForTimeout(500);
console.log('resumed', await page.evaluate(() => window.__nightfall.game.state));
// death
await page.evaluate(() => { const g = window.__nightfall.game; g.player.godMode = false; g.player.health = 5; g.damagePlayer(100); });
await page.waitForTimeout(3000);
console.log('death', await page.evaluate(() => ({ state: window.__nightfall.game.state, overlay: !document.getElementById('gameover').classList.contains('hidden'), title: document.getElementById('result-title').textContent })));
await page.screenshot({ path: '/tmp/opencode/shots/v-lose.jpg', type: 'jpeg', quality: 85 });
console.log('errors', errs.length, errs.slice(0, 5));
await browser.close();

import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errs = [];
page.on('pageerror', e => { errs.push(e.message); console.log('PAGEERROR:', e.message); });
page.on('console', m => { if (m.type() === 'error') { errs.push(m.text()); console.log('CONSOLE:', m.text()); } });
await page.goto('http://localhost:3002/', { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(3500);
await page.getByLabel('Play Now').click();
await page.waitForTimeout(3000);
const info = () => page.evaluate(() => window.__nightfall.state_info());
await page.evaluate(() => { window.__nightfall.game.player.godMode = true; });
console.log('start', await info());

async function waitWave(n) {
  for (let i = 0; i < 120; i++) {
    const s = await info();
    if (s.wave === n && s.active) return s;
    if (s.pending === n) await page.evaluate(() => { const g = window.__nightfall.game; if (g.intermission > 0.1) g.intermission = 0.1; });
    await page.waitForTimeout(300);
  }
  throw new Error('wave ' + n + ' never started');
}
async function clearWave(n) {
  for (let i = 0; i < 120; i++) {
    const s = await info();
    if (s.wave === n && !s.active && (n === 5 || s.pending === n + 1)) return s;
    if (s.wave === n && s.active) {
      await page.evaluate(() => {
        const g = window.__nightfall.game;
        g.enemies.queue = [];
        window.__nightfall.killAll();
      });
    } else if (s.inter > 0.1) {
      await page.evaluate(() => { window.__nightfall.game.intermission = 0.1; });
    }
    await page.waitForTimeout(300);
  }
  throw new Error('wave ' + n + ' never cleared: ' + JSON.stringify(await info()));
}

for (let w = 1; w <= 5; w++) {
  console.log('wait wave', w, await waitWave(w));
  if (w === 5) {
    // spawn boss manually to verify boss presentation
    await page.evaluate(() => {
      const g = window.__nightfall.game;
      g.player.position.set(0, 0, 16); g.player.yaw = 0; g.player.pitch = 0;
      const b = g.enemies.spawn('heavy');
      b.position.set(0.6, 0, 8.5); b.group.position.set(0.6, 0, 8.5); b.state = 'seek'; b.spawnT = 1;
      b.group.scale.setScalar(b.scale);
      g.enemies.queue = [];
      g.enemies.enemies.forEach(e => { if (e.type !== 'heavy') window.__nightfall.enemies.kill(e, false, e.position.clone(), null); });
    });
    await page.waitForTimeout(900);
    console.log('boss state', await page.evaluate(() => { const g = window.__nightfall.game; const b = g.enemies.enemies.find(e => e.type === 'heavy'); return { exists: !!b, health: b?.health, bossBar: !document.getElementById('boss-bar').classList.contains('hidden'), banner: document.getElementById('wave-banner').className }; }));
    await page.screenshot({ path: '/tmp/opencode/shots/v-boss.jpg', type: 'jpeg', quality: 85 });
  }
  const cleared = await clearWave(w);
  console.log('cleared would-be wave', w, cleared);
}
await page.waitForTimeout(3500);
console.log('win', await page.evaluate(() => ({ state: window.__nightfall.game.state, overlay: !document.getElementById('gameover').classList.contains('hidden'), title: document.getElementById('result-title').textContent, score: document.querySelector('#stat-score')?.textContent })));
await page.screenshot({ path: '/tmp/opencode/shots/v-win.jpg', type: 'jpeg', quality: 85 });

// redeploy and subsystem checks
await page.getByLabel('Play Again').click();
await page.waitForTimeout(2500);
console.log('redeployed', await info());
await page.evaluate(() => { const g = window.__nightfall.game; g.player.godMode = true; g.weapons.ammo.rifle.mag = 4; g.weapons.reload(); });
await page.waitForTimeout(2400);
console.log('reload', await page.evaluate(() => ({ mag: window.__nightfall.game.weapons.ammo.rifle.mag, reloading: window.__nightfall.game.weapons.reloading })));
await page.evaluate(() => window.__nightfall.game.weapons.switchImmediate('pistol'));
await page.waitForTimeout(600);
console.log('switch', await page.evaluate(() => ({ cur: window.__nightfall.game.weapons.current, name: document.getElementById('weapon-name').textContent, slot2: document.getElementById('slot-2').className })));
console.log('nade', await page.evaluate(() => { const g = window.__nightfall.game; const before = g.weapons.grenades; g.weapons.grenadeCooldown = 0; g.weapons.throwGrenade(); return { before, after: g.weapons.grenades, projectiles: g.weapons.projectiles.length }; }));
await page.keyboard.press('Escape');
await page.waitForTimeout(500);
console.log('paused', await page.evaluate(() => ({ state: window.__nightfall.game.state, overlay: !document.getElementById('pause').classList.contains('hidden') })));
await page.screenshot({ path: '/tmp/opencode/shots/v-pause.jpg', type: 'jpeg', quality: 85 });
await page.getByLabel('Resume').click();
await page.waitForTimeout(500);
console.log('resumed', await page.evaluate(() => window.__nightfall.game.state));
await page.evaluate(() => { const g = window.__nightfall.game; g.player.godMode = false; g.player.health = 5; g.damagePlayer(100); });
await page.waitForTimeout(3500);
console.log('death', await page.evaluate(() => ({ state: window.__nightfall.game.state, overlay: !document.getElementById('gameover').classList.contains('hidden'), title: document.getElementById('result-title').textContent })));
await page.screenshot({ path: '/tmp/opencode/shots/v-lose.jpg', type: 'jpeg', quality: 85 });
console.log('errors', errs.length, errs.slice(0, 5));
await browser.close();

