96:       const d = new THREE.Vector3(normal.x + rand(-0.8, 0.8), normal.y + rand(-0.4, 1.0), normal.z + rand(-0.8, 0.8)).normalize();
97:       const v = speed * rand(0.35, 1.35);
98:       const data = this.sparkData[i];
