120:   tracer(from, to, color = 0xffd9a0, width = 1) {
121:     let t = this.tracerPool.find(o => !o.active);
122:     if (!t) {
123:       const geo = new THREE.BufferGeometry();
124:       geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(6), 3));
125:       const mat = new THREE.LineBasicMaterial({ color, transparent: true, opacity: 1, blending: THREE.AdditiveBlending, depthWrite: false });
126:       const line = new THREE.Line(geo, mat); line.frustumCulled = false; this.scene.add(line);
127:       t = { line, active: false, life: 0, max: 1 }; this.tracerPool.push(t);
128:     }
129:     t.active = true; t.life = 0.075; t.max = 0.075; t.line.visible = true;
130:     t.line.material.color.setHex(color); t.line.material.opacity = 0.95;
131:     const a = t.line.geometry.attributes.position;
132:     a.setXYZ(0, from.x, from.y, from.z); a.setXYZ(1, to.x, to.y, to.z); a.needsUpdate = true;
133:     // bright head glow
134:     this.spawnSparks(to, new THREE.Vector3(0, 1, 0), 1, 0xffe4b0, 0.2);
135:   }
