138:     const sp = new THREE.Sprite(new THREE.SpriteMaterial({ map: this.glow, color, transparent: true, opacity: 1, depthWrite: false, blending: THREE.AdditiveBlending }));
139:     sp.position.copy(pos); sp.scale.setScalar(rand(0.35, 0.55) * scale); this.scene.add(sp);
140:     let light = null;
