150:   spawnSmoke(pos, dir, scale = 1, life = 0.8, opacity = 0.3) {
151:     const s = this.smoke[this.smokeCursor]; this.smokeCursor = (this.smokeCursor + 1) % this.smoke.length;
152:     s.sprite.visible = true; s.sprite.position.copy(pos).addScaledVector(dir, 0.1);
153:     s.life = life; s.max = life; s.vy = rand(0.2, 0.6); s.scale = scale * rand(0.7, 1.2); s.grow = rand(1.6, 2.8);
154:     s.opacity = opacity;
155:     s.sprite.scale.setScalar(s.scale); s.sprite.material.opacity = opacity;
156:   }
