159:     const color = materialType === 'metal' ? 0xffd68a : materialType === 'wood' ? 0xd5a46a : 0xffb063;
160:     this.spawnSparks(point, normal, materialType === 'metal' ? 14 : 8, color, materialType === 'metal' ? 7 : 4.5);
161:     this.spawnSmoke(point, normal, rand(0.3, 0.6), rand(0.4, 0.9), 0.22);
162:     this.spawnDecal(point, normal);
163:     this.audio?.impact?.(materialType);
164:   }
165: 
166:   spawnDecal(point, normal) {
167:     let d = this.decals.find(o => !o.active);
168:     if (!d) {
169:       if (this.decals.length > 70) { d = this.decals.shift(); }
170:       else {
171:         const mesh = new THREE.Mesh(new THREE.CircleGeometry(0.09, 8), new THREE.MeshBasicMaterial({ map: this.glow, color: 0x090909, transparent: true, opacity: 0.85, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -2 }));
172:         this.scene.add(mesh); d = { mesh, active: false, life: 0 };
173:       }
174:     }
175:     d.active = true; d.life = 30;
176:     d.mesh.visible = true; d.mesh.material.opacity = 0.55;
177:     d.mesh.position.copy(point).addScaledVector(normal, 0.012);
178:     d.mesh.lookAt(point.clone().add(normal));
179:     d.mesh.rotateZ(rand(0, Math.PI * 2));
180:     d.mesh.scale.setScalar(rand(0.6, 1.35));
181:     this.decals.push(d);
182:   }
183: 
184:   shell(pos, dir) {
185:     const s = this.shells[this.shellCursor]; this.shellCursor = (this.shellCursor + 1) % this.shells.length;
186:     s.life = 1.6; s.mesh.visible = true; s.mesh.position.copy(pos);
187:     s.mesh.rotation.set(rand(0, 6), rand(0, 6), rand(0, 6));
188:     s.vx = dir.x * rand(0.8, 2) + rand(-0.6, 0.6);
189:     s.vy = rand(1.2, 2.6);
190:     s.vz = dir.z * rand(0.8, 2) + rand(-0.6, 0.6);
191:     s.spin.set(rand(-14, 14), rand(-14, 14), rand(-14, 14));
192:     s.bounced = false;
193:   }
194: 
195:   explosion(point, radius = 7) {
196:     const sphere = new THREE.Mesh(new THREE.SphereGeometry(1, 16, 12), new THREE.MeshBasicMaterial({ color: 0xffcf8a, transparent: true, opacity: 0.95, blending: THREE.AdditiveBlending, depthWrite: false }));
197:     sphere.position.copy(point); this.scene.add(sphere);
198:     const ring = new THREE.Mesh(new THREE.RingGeometry(0.6, 1, 32), new THREE.MeshBasicMaterial({ color: 0xffa45a, transparent: true, opacity: 0.8, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false }));
199:     ring.position.copy(point); ring.rotation.x = -Math.PI / 2; this.scene.add(ring);
200:     const light = new THREE.PointLight(0xffa24a, 90, radius * 4, 2); light.position.copy(point).add(new THREE.Vector3(0, 1, 0)); this.scene.add(light);
201:     this.flashes.push({ sphere, ring, light, life: 0.55, max: 0.55, explosion: true });
202:     for (let i = 0; i < 55; i++) {
203:       const n = new THREE.Vector3(rand(-1, 1), rand(-0.2, 1), rand(-1, 1)).normalize();
204:       const p = point.clone().addScaledVector(n, rand(0.2, 1.2));
205:       this.spawnSparks(p, n, 1, i % 3 === 0 ? 0xffe0a0 : 0xff7b2e, rand(9, 22));
206:     }
207:     for (let i = 0; i < 8; i++) {
208:       this.spawnSmoke(point.clone().add(new THREE.Vector3(rand(-1.6, 1.6), rand(0, 2), rand(-1.6, 1.6))), new THREE.Vector3(0, 1, 0), rand(1.4, 3), rand(1.4, 2.6), 0.38);
209:     }
210:     this.audio?.explosion?.();
211:   }
212: 
213:   update(dt) {
214:     this.time += dt;
215: 
216:     // tracers
217:     for (const t of this.tracerPool) {
218:       if (!t.active) continue;
219:       t.life -= dt;
220:       t.line.material.opacity = Math.max(0, t.life / t.max) * 0.95;
221:       if (t.life <= 0) { t.active = false; t.line.visible = false; }
222:     }
223:     // flashes
224:     for (let i = this.flashes.length - 1; i >= 0; i--) {
225:       const f = this.flashes[i]; f.life -= dt;
226:       const k = Math.max(0, f.life / f.max);
227:       if (f.sphere) {
228:         const s = 1 + (1 - k) * 6;
229:         f.sphere.scale.setScalar(s); f.sphere.material.opacity = k * 0.85;
230:         f.ring.scale.setScalar(1 + (1 - k) * 14); f.ring.material.opacity = k * 0.6;
231:         f.light.intensity = 90 * k;
232:       } else {
233:         f.sprite.material.opacity = k; f.sprite.scale.setScalar(f.sprite.scale.x * (1 + dt * 4));
234:         if (f.light) f.light.intensity = 14 * k;
235:       }
236:       if (f.life <= 0) {
237:         if (f.sprite) { this.scene.remove(f.sprite); f.sprite.material.dispose(); }
238:         if (f.sphere) { this.scene.remove(f.sphere); this.scene.remove(f.ring); f.sphere.material.dispose(); f.ring.material.dispose(); }
239:         if (f.light) this.scene.remove(f.light);
240:         this.flashes.splice(i, 1);
241:       }
242:     }
243:     // spark particles
244:     const sp = this.sparkGeo.attributes.position; let dirty = false;
245:     for (let i = 0; i < this.sparkCount; i++) {
246:       const d = this.sparkData[i];
247:       if (d.life <= 0) continue;
248:       d.life -= dt; dirty = true;
249:       if (d.life <= 0) { sp.setXYZ(i, 0, -9999, 0); continue; }
250:       d.vy -= 13 * dt;
251:       sp.setXYZ(i, sp.getX(i) + d.vx * dt, sp.getY(i) + d.vy * dt, sp.getZ(i) + d.vz * dt);
252:     }
253:     if (dirty) sp.needsUpdate = true;
254:     // blood
255:     const bp = this.bloodGeo.attributes.position; let bdirty = false;
256:     for (let i = 0; i < this.bloodCount; i++) {
257:       const d = this.bloodData[i];
258:       if (d.life <= 0) continue;
259:       d.life -= dt; bdirty = true;
260:       if (d.life <= 0) { bp.setXYZ(i, 0, -9999, 0); continue; }
261:       d.vy -= 9 * dt;
262:       bp.setXYZ(i, bp.getX(i) + d.vx * dt, bp.getY(i) + d.vy * dt, bp.getZ(i) + d.vz * dt);
263:     }
264:     if (bdirty) bp.needsUpdate = true;
265:     // shells
266:     for (const s of this.shells) {
267:       if (s.life <= 0) continue;
268:       s.life -= dt;
269:       if (s.life <= 0) { s.mesh.visible = false; continue; }
270:       s.vy -= 15 * dt;
271:       s.mesh.position.x += s.vx * dt; s.mesh.position.y += s.vy * dt; s.mesh.position.z += s.vz * dt;
272:       s.mesh.rotation.x += s.spin.x * dt; s.mesh.rotation.y += s.spin.y * dt; s.mesh.rotation.z += s.spin.z * dt;
273:       if (s.mesh.position.y < 0.02) {
274:         s.mesh.position.y = 0.02;
275:         if (!s.bounced) { s.vy = -s.vy * 0.35; s.vx *= 0.5; s.vz *= 0.5; s.bounced = true; }
276:         else { s.vy = 0; s.vx *= 0.75; s.vz *= 0.75; }
277:         s.spin.multiplyScalar(0.7);
278:       }
279:     }
280:     // smoke
281:     for (const s of this.smoke) {
282:       if (s.life <= 0) { if (s.sprite.visible) s.sprite.visible = false; continue; }
283:       s.life -= dt;
284:       const k = Math.max(0, s.life / s.max);
285:       s.sprite.material.opacity = k * s.opacity;
286:       s.sprite.scale.setScalar(s.scale * (1 + (1 - k) * s.grow));
287:       s.sprite.position.y += s.vy * dt;
288:       if (s.life <= 0) s.sprite.visible = false;
289:     }
290:     // decals fade
291:     for (const d of this.decals) {
292:       if (!d.active) continue;
293:       d.life -= dt;
294:       if (d.life < 3) d.mesh.material.opacity = Math.max(0, d.life / 3) * 0.55;
295:       if (d.life <= 0) { d.active = false; d.mesh.visible = false; }
296:     }
297:   }
298: 
299:   dispose() {
300:     for (const t of this.tracerPool) this.scene.remove(t.line);
301:     for (const d of this.decals) this.scene.remove(d.mesh);
302:     for (const s of this.shells) this.scene.remove(s.mesh);
303:     for (const s of this.smoke) this.scene.remove(s.sprite);
304:     for (const f of this.flashes) this.scene.remove(f.light);
305:     this.scene.remove(this.sparks); this.scene.remove(this.blood);
306:   }
307: }

