input.content:
import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errs = [];
page.on('pageerror', e => { errs.push(e.message); console.log('PAGEERROR:', e.message); });
page.on('console', m => { if (m.type() === 'error') { errs.push(m.text()); console.log('CONSOLE:', m.text()); } });
await page.goto('http://localhost:3002/', { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(3200);
await page.getByLabel('Play Now').click();
await page.waitForTimeout(2500);
const info = () => page.evaluate(() => window.__nightfall.state_info());
await page.evaluate(() => { window.__nightfall.game.player.godMode = true; });
console.log('start', await info());

async function waitWave(n) {
  for (let i = 0; i < 100; i++) {
    const s = await info();
    if (s.wave === n && s.active) return s;
    await page.evaluate(() => { const g = window.__nightfall.game; if (g.intermission > 0.1) g.intermission = 0.1; });
    await page.waitForTimeout(250);
  }
  throw new Error('wave ' + n + ' never started');
}
async function clearWave(n) {
  for (let i = 0; i < 100; i++) {
    const s = await info();
    if (s.wave === n && !s.active) return s;
    if (s.wave === n) await page.evaluate(() => { const g = window.__nightfall.game; g.enemies.queue = []; window.__nightfall.killAll(); });
    await page.waitForTimeout(250);
  }
  throw new Error('wave ' + n + ' never cleared: ' + JSON.stringify(await info()));
}
for (let w = 1; w <= 4; w++) {
  await waitWave(w);
  console.log('cleared', (await clearWave(w)).score);
}
await waitWave(5);
await page.evaluate(() => {
  const g = window.__nightfall.game;
  g.player.position.set(0, 0, 16); g.player.yaw = 0; g.player.pitch = 0.02;
  g.enemies.queue = [];
  g.enemies.enemies.forEach(e => window.__nightfall.enemies.kill(e, false, e.position.clone(), null));
  const b = g.enemies.spawn('heavy');
  b.position.set(0.2, 0, 9); b.group.position.set(0.2, 0, 9); b.state = 'seek'; b.spawnT = 1;
  b.group.scale.setScalar(b.scale);
  g.weapons.setAim?.(1);
});
await page.waitForTimeout(1200);
await page.screenshot({ path: '/tmp/opencode/shots/z-boss.jpg', type: 'jpeg', quality: 86 });
// kill boss to trigger victory
await page.evaluate(() => window.__nightfall.killAll());
await page.waitForTimeout(1000);
console.log('victory state', await info());
for (let i = 0; i < 40; i++) {
  if (await page.evaluate(() => window.__nightfall.game.state === 'won')) break;
  await page.waitForTimeout(500);
}
console.log('won', await page.evaluate(() => ({ state: window.__nightfall.game.state, overlay: !document.getElementById('gameover').classList.contains('hidden'), title: document.getElementById('result-title').textContent, kicker: document.getElementById('result-kicker').textContent, kills: document.getElementById('stat-kills').textContent, waves: document.getElementById('stat-waves').textContent, score: document.getElementById('stat-score').textContent })));
await page.screenshot({ path: '/tmp/opencode/shots/z-win.jpg', type: 'jpeg', quality: 86 });
// restart and test reload + death result
await page.getByLabel('Play Again').click();
await page.waitForTimeout(1800);
await page.evaluate(() => { const g = window.__nightfall.game; g.player.godMode = true; g.weapons.ammo.rifle.mag = 4; g.weapons.fireTimer = 0; g.weapons.reload(); });
await page.waitForTimeout(5000);
console.log('reload', await page.evaluate(() => ({ mag: window.__nightfall.game.weapons.ammo.rifle.mag, reloading: window.__nightfall.game.weapons.reloading })));
await page.evaluate(() => { const g = window.__nightfall.game; g.player.godMode = false; g.player.invuln = 0; g.player.health = 10; window.__nightfall.damagePlayer(100); });
await page.waitForTimeout(500);
console.log('dying', await info());
for (let i = 0; i < 30; i++) {
  if (await page.evaluate(() => window.__nightfall.game.state === 'gameover')) break;
  await page.waitForTimeout(500);
}
console.log('dead', await page.evaluate(() => ({ state: window.__nightfall.game.state, overlay: !document.getElementById('gameover').classList.contains('hidden'), title: document.getElementById('result-title').textContent, kicker: document.getElementById('result-kicker').textContent })));
await page.screenshot({ path: '/tmp/opencode/shots/z-lose.jpg', type: 'jpeg', quality: 86 });
console.log('errors', errs.length, errs.slice(0, 5));
await browser.close();

