import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errs = [];
page.on('pageerror', e => { errs.push(e.message); console.log('PAGEERROR:', e.message); });
page.on('console', m => { if (m.type() === 'error') { errs.push(m.text()); console.log('CONSOLE:', m.text()); } });
await page.goto('http://localhost:3002/', { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(3200);
await page.screenshot({ path: '/tmp/opencode/shots/x-menu.jpg', type: 'jpeg', quality: 85 });
await page.getByLabel('Play Now').click();
await page.waitForTimeout(5000);
await page.evaluate(() => { const g = window.__nightfall.game; g.player.godMode = true; g.player.position.set(0, 0, 17); g.player.yaw = 0; g.player.pitch = -0.02; });
await page.waitForTimeout(1200);
await page.screenshot({ path: '/tmp/opencode/shots/x-play.jpg', type: 'jpeg', quality: 86 });
// ADS
await page.evaluate(() => { window.__nightfall.game.input.mouse.right = true; });
await page.waitForTimeout(1500);
await page.screenshot({ path: '/tmp/opencode/shots/x-ads.jpg', type: 'jpeg', quality: 86 });
await page.evaluate(() => { window.__nightfall.game.input.mouse.right = false; });
// reload logic quick-forward
await page.evaluate(() => {
  const w = window.__nightfall.game.weapons;
  w.ammo.rifle.mag = 4; w.reloading = false; w.reload();
  for (let i = 0; i < 60; i++) w.update(0.05);
});
console.log('reload', await page.evaluate(() => { const w = window.__nightfall.game.weapons; return { mag: w.ammo.rifle.mag, reserve: w.ammo.rifle.reserve, reloading: w.reloading }; }));
console.log('fire', await page.evaluate(() => { const w = window.__nightfall.game.weapons; const before = w.ammo.rifle.mag; w.fireTimer = 0; w.fire(); return { before, after: w.ammo.rifle.mag, tracers: w.fx.tracerPool.filter(t => t.active).length, flashes: w.fx.flashes.length }; }));
// death overlay
await page.evaluate(() => { const g = window.__nightfall.game; g.player.godMode = false; g.player.invuln = 0; g.player.health = 5; window.__nightfall.damagePlayer(100); });
await page.waitForTimeout(500);
console.log('dying', await page.evaluate(() => window.__nightfall.game.state));
for (let i = 0; i < 30; i++) {
  if (await page.evaluate(() => window.__nightfall.game.state === 'gameover')) break;
  await page.waitForTimeout(400);
}
console.log('dead', await page.evaluate(() => ({ state: window.__nightfall.game.state, overlay: !document.getElementById('gameover').classList.contains('hidden'), title: document.getElementById('result-title').textContent, kicker: document.getElementById('result-kicker').textContent })));
await page.screenshot({ path: '/tmp/opencode/shots/x-lose.jpg', type: 'jpeg', quality: 86 });
// mobile view
const mp = await browser.newPage({ viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true, deviceScaleFactor: 2 });
mp.on('pageerror', e => console.log('MOBILE PAGEERROR:', e.message));
await mp.goto('http://localhost:3002/', { waitUntil: 'load', timeout: 60000 });
await mp.waitForTimeout(3500);
await mp.screenshot({ path: '/tmp/opencode/shots/x-mobilemenu.jpg', type: 'jpeg', quality: 85 });
await mp.getByLabel('Play Now').click();
await mp.waitForTimeout(5000);
await mp.screenshot({ path: '/tmp/opencode/shots/x-mobileplay.jpg', type: 'jpeg', quality: 85 });
console.log('touch', await mp.evaluate(() => ({ isTouch: window.__nightfall.game.input.isTouch, controls: !document.getElementById('touch-controls').classList.contains('hidden'), state: window.__nightfall.game.state })));
console.log('errors', errs.length, errs.slice(0, 5));
await browser.close();

