import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const mp = await browser.newPage({ viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true, deviceScaleFactor: 2 });
await mp.goto('http://localhost:3002/', { waitUntil: 'load', timeout: 60000 });
await mp.waitForTimeout(3200);
await mp.getByLabel('Play Now').click();
await mp.waitForTimeout(4000);
console.log(await mp.evaluate(() => {
  const sels = ['.hud-top-left','.mission-tag','.radar-wrap','#objective','.hud-top-center','.wave-label','.hostiles','.hud-top-right','.score-block','.rotate-hint','.hud-bottom-left','.health-track','.equip-row','.hud-bottom-right','.weapon-name','.ammo-row','.stick-zone','.touch-buttons','.t-fire','.t-small'];
  const out = {};
  for (const s of sels) {
    const el = document.querySelector(s);
    if (!el) { out[s] = null; continue; }
    const r = el.getBoundingClientRect();
    out[s] = { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height), disp: getComputedStyle(el).display };
  }
  out.viewport = { w: innerWidth, h: innerHeight };
  return out;
}));
await browser.close();

